/* Interface do portal: os dados, preços e permissões são validados no servidor. */
const app=document.querySelector('#app'),dialog=document.querySelector('#details'),detail=document.querySelector('#details-content');
const state={user:null,csrf:'',config:null,orders:[],admin:null,tab:['tasks-bi','fiscal','finance','orders','maintenance'].includes(new URLSearchParams(location.search).get('view'))?new URLSearchParams(location.search).get('view'):'overview',authTab:'login',selected:null};
const money=c=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format((c||0)/100);
const date=v=>v?new Intl.DateTimeFormat('pt-BR',{timeZone:'America/Sao_Paulo',dateStyle:'short'}).format(new Date(v.length===10?v+'T15:00:00Z':v)):'—';
const escapeHtml=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const statusLabels={NOT_CREATED:'Sem cobrança',PENDING:'Aguardando pagamento',CONFIRMED:'Confirmado',RECEIVED:'Recebido',RECEIVED_IN_CASH:'Recebido em dinheiro',OVERDUE:'Vencido',REFUNDED:'Estornado',REFUND_REQUESTED:'Estorno solicitado',REFUND_IN_PROGRESS:'Estorno em andamento',DELETED:'Excluído',CHARGEBACK_REQUESTED:'Contestação',CHARGEBACK_DISPUTE:'Em disputa',AWAITING_CHARGEBACK_REVERSAL:'Aguardando reversão',DUNNING_RECEIVED:'Recuperado',DUNNING_REQUESTED:'Em cobrança',PARTIALLY_REFUNDED:'Estorno parcial',solicitado:'Solicitado',planejamento:'Planejamento',desenvolvimento:'Desenvolvimento',revisao:'Em revisão',entregue:'Entregue',checkout:'Aguardando autorização',active:'Ativa',inactive:'Inativa',uncertain:'Em conciliação',cancel_requested:'Cancelamento solicitado',canceled:'Cancelada',expired:'Autorização expirada',creating:'Processando'};
const badge=s=>`<span class="badge ${['RECEIVED','CONFIRMED','RECEIVED_IN_CASH','active','entregue'].includes(s)?'good':['OVERDUE','REFUNDED','CHARGEBACK_REQUESTED','uncertain'].includes(s)?'bad':['PENDING','checkout','cancel_requested'].includes(s)?'warn':''}">${escapeHtml(statusLabels[s]||s)}</span>`;
function notify(message,error=false){const n=document.querySelector('#notice');n.textContent=message;n.className=error?'error':'';n.hidden=false;clearTimeout(notify.timer);notify.timer=setTimeout(()=>n.hidden=true,9000)}
async function api(path,options={}){const response=await fetch(path,{...options,credentials:'same-origin',headers:{'Content-Type':'application/json',...(state.csrf?{'X-CSRF-Token':state.csrf}:{}),...options.headers}});let data;try{data=await response.json()}catch{throw Error('O servidor não retornou uma resposta válida.')}if(!response.ok){if(response.status===401&&state.user){state.user=null;renderAuth()}throw Error(data.error||'Não foi possível concluir.')}return data}
const post=(path,data={})=>api(path,{method:'POST',body:JSON.stringify(data)});
async function task(button,fn){const text=button?.textContent;if(button){button.disabled=true;button.textContent='Aguarde…'}try{await fn()}catch(error){notify(error.message,true)}finally{if(button){button.disabled=false;button.textContent=text}}}
function externalLink(url,label,classes='btn secondary'){try{const u=new URL(url);if(u.protocol!=='https:'||!(u.hostname==='asaas.com'||u.hostname.endsWith('.asaas.com')))return '';return `<a class="${classes}" href="${escapeHtml(url)}" target="_blank" rel="noopener noreferrer">${label} ↗</a>`}catch{return ''}}
function renderAuth(){document.title='Entrar | Imagine';app.innerHTML=`<div class="auth-layout"><section class="auth-brand"><a href="/" class="logo-box"><img class="logo" src="assets/logo-imagine.png" alt="Imagine Comunicação Digital"></a><div><span class="eyebrow">Seu espaço Imagine</span><h1>Seu projeto.<br>Mais perto.<br><span>Em cada etapa.</span></h1><p>Acompanhe seus pedidos, consulte pagamentos e converse com nossa equipe em um só lugar.</p></div><div class="auth-region">TODO O BRASIL · ESTADOS UNIDOS · PORTUGAL</div></section><section class="auth-form"><span class="eyebrow">Portal do cliente</span><h2>${state.authTab==='login'?'Bom ter você aqui.':'Vamos começar?'}</h2><p class="muted">${state.authTab==='login'?'Entre para acompanhar seus projetos.':'Crie sua conta e conte o que precisa desenvolver.'}</p><div class="auth-tabs"><button data-auth="login" class="${state.authTab==='login'?'active':''}">Entrar</button><button data-auth="register" class="${state.authTab==='register'?'active':''}">Criar conta</button></div><form id="auth-form">${state.authTab==='register'?'<label class="field"><span>Seu nome</span><input name="name" autocomplete="name" required maxlength="120"></label>':''}<label class="field"><span>E-mail</span><input type="email" name="email" autocomplete="email" required maxlength="254"></label><label class="field"><span>Senha ${state.authTab==='register'?'· mínimo de 12 caracteres':''}</span><input type="password" name="password" autocomplete="${state.authTab==='register'?'new-password':'current-password'}" required ${state.authTab==='register'?'minlength="12"':''} maxlength="128"></label><button class="btn orange full" type="submit">${state.authTab==='login'?'Entrar na minha conta':'Criar minha conta'} ↗</button></form><p class="fine">O pagamento é concluído no Asaas. Seus dados de cartão não são recebidos por este portal.</p><div class="auth-footer"><a class="text-link" href="https://wa.me/5585996632689" target="_blank" rel="noopener noreferrer">Precisa de ajuda com o acesso? Fale pelo WhatsApp ↗</a></div></section></div>`;document.querySelectorAll('[data-auth]').forEach(b=>b.onclick=()=>{state.authTab=b.dataset.auth;renderAuth()});document.querySelector('#auth-form').onsubmit=e=>{e.preventDefault();task(e.submitter,async()=>{const data=Object.fromEntries(new FormData(e.target));const result=await post('/api/'+state.authTab,data);state.user=result.user;state.csrf=result.csrf;await load();render();const requested=new URLSearchParams(location.search).get('product');if(requested&&state.user.role==='client')newOrder(requested)})}}
const adminTabs=[['overview','◫','Visão geral'],['orders','▤','Pedidos'],['finance','◈','Financeiro'],['fiscal','▧','Notas fiscais'],['bi','▥','BI · Gestão'],['clients','◉','Clientes'],['catalog','⊞','Catálogo'],['activity','↻','Atividades'],['tasks-bi','▥','BI · Atividades'],['team','◉','Equipe e acessos'],['account','⚙','Minha conta']];
const clientTabs=[['overview','◫','Visão geral'],['orders','▤','Meus pedidos'],['finance','◈','Pagamentos'],['fiscal','▧','Notas fiscais'],['maintenance','↻','Manutenção e suporte'],['solutions','⊞','Novo projeto'],['account','⚙','Minha conta']];
async function load(){const [orders,config]=await Promise.all([api('/api/orders'),api('/api/config')]);state.orders=orders.orders;state.config=config;if(state.user.role==='admin')state.admin=await api('/api/admin/dashboard')}
function render(){if(!state.user)return renderAuth();const admin=state.user.role==='admin',tabs=admin?adminTabs.filter(t=>!state.user.staff_profile||state.user.permissions.includes(t[0])):clientTabs;if(!tabs.some(t=>t[0]===state.tab))state.tab='overview';document.title=(admin?'Administração':'Portal do Cliente')+' | Imagine';app.innerHTML=`<div class="shell"><aside class="sidebar"><a href="/"><img class="logo" src="assets/logo-imagine.png" alt="Imagine Comunicação Digital"></a><div><p class="side-title">${admin?'Administração':'Área do cliente'}</p><nav class="side-nav" aria-label="Menu do portal">${tabs.map(([id,icon,label])=>`<button data-tab="${id}" class="${state.tab===id?'active':''}"><span class="side-icon" aria-hidden="true">${icon}</span>${label}</button>`).join('')}</nav></div><div class="side-bottom">Ideias que viram soluções.<br>Brasil · Estados Unidos · Portugal<br><a href="https://wa.me/5585996632689" target="_blank" rel="noopener noreferrer">WhatsApp ↗</a></div></aside><main class="main"><header class="topbar"><span class="topbar-label">Imagine / ${escapeHtml(tabs.find(t=>t[0]===state.tab)?.[2]||'Portal')}</span><div class="identity"><span class="avatar">${escapeHtml(state.user.name.slice(0,1).toUpperCase())}</span><span>${escapeHtml(state.user.name)}</span><button class="logout" id="logout">Sair</button></div></header><div class="content">${state.config.environment==='sandbox'&&!(state.user.role==='client'&&['orders','finance','maintenance'].includes(state.tab))?'<div class="banner">Ambiente de testes do Asaas. As cobranças de teste não representam pagamentos reais.</div>':''}${!state.config.billingReady&&!(state.user.role==='client'&&['orders','maintenance'].includes(state.tab))?'<div class="banner">Pagamentos online ainda não foram ativados. Você já pode registrar seu projeto e acompanhar propostas.</div>':''}<div id="view"></div><footer class="portal-footer"><span>Imagine Comunicação Digital · Seu projeto em movimento.</span><a href="https://wa.me/5585996632689" target="_blank" rel="noopener noreferrer">WhatsApp · +55 (85) 99663-2689 ↗</a></footer></div></main></div>`;document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{state.tab=b.dataset.tab;render()});document.querySelector('#logout').onclick=e=>task(e.currentTarget,async()=>{await post('/api/logout');state.user=null;state.csrf='';renderAuth()});renderView()}
const head=(title,subtitle,action='')=>`<div class="page-head"><div><span class="eyebrow">${state.user.role==='admin'?'Gestão Imagine':'Seu espaço Imagine'}</span><h1>${title}</h1><p>${subtitle}</p></div>${action}</div>`;
function orderTable(orders){return orders.length?`<div class="table-wrap"><table><thead><tr><th>Pedido</th>${state.user.role==='admin'?'<th>Cliente</th>':''}<th>Investimento</th><th>Projeto</th><th>Pagamento</th><th></th></tr></thead><tbody>${orders.map(o=>`<tr><td><strong>${escapeHtml(o.title)}</strong><small>#${o.id.slice(0,8)} · ${date(o.created_at)}</small></td>${state.user.role==='admin'?`<td>${escapeHtml(o.client.name)}<small>${escapeHtml(o.client.email)}</small></td>`:''}<td>${o.price_cents?money(o.price_cents):'Sob proposta'}</td><td>${badge(o.phase)}</td><td>${badge(o.payment_status)}</td><td><button class="btn secondary" data-order="${o.id}">Ver pedido ↗</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Seus projetos aparecerão aqui. Comece contando sua próxima ideia.</div>'}
function paymentTable(payments){return payments.length?`<div class="table-wrap"><table><thead><tr><th>Pedido / cobrança</th><th>Tipo</th><th>Valor bruto</th><th>Vencimento</th><th>Status</th><th></th></tr></thead><tbody>${payments.map(p=>`<tr><td>#${p.order_id.slice(0,8)}<small>${escapeHtml(p.id)}</small></td><td>${p.kind==='maintenance'?'Manutenção':'Projeto'}</td><td>${money(p.value_cents)}</td><td>${date(p.due_date)}</td><td>${badge(p.status)}</td><td>${['PENDING','OVERDUE'].includes(p.status)?externalLink(p.invoice_url,'Pagar'):''}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Nenhuma cobrança registrada por enquanto.</div>'}
function stats(items){return `<div class="stats">${items.map(([label,value,note])=>`<div class="stat"><span class="stat-label">${label}</span><strong>${value}</strong><small>${note}</small></div>`).join('')}</div>`}
function renderView(){clearTimeout(loadOverview.timer);const view=document.querySelector('#view'),admin=state.user.role==='admin',payments=state.orders.flatMap(o=>o.payments),m=state.admin?.metrics;let html='';
 if(state.tab==='overview'){html=head('Olá, '+escapeHtml(state.user.name.split(' ')[0])+'.',admin?'Acompanhe a operação e as cobranças dos projetos.':'Seu próximo passo está aqui.',!admin?'<button class="btn orange" id="new-order">Novo projeto +</button>':'<button class="btn secondary" id="refresh">Atualizar dados ↻</button>');if(admin){html+=stats([['Recebido',money(m.received),'Valor bruto liquidado'],['Confirmado',money(m.confirmed),'Ainda não somado ao recebido'],['A receber',money(m.pending),'Cobranças pendentes'],['Vencido',money(m.overdue),'Cobranças em atraso']]);html+=`<div class="banner">Visão das cobranças geradas por este portal. Não representa o saldo bancário nem todas as movimentações da conta Asaas. ${m.eventsPending?m.eventsPending+' evento(s) aguardando conciliação.':''}</div>`}else{html+=`<div class="hero-panel"><div><span class="eyebrow">Da ideia à realização</span><h2>Mais clareza para acompanhar<br>cada etapa do seu projeto.</h2><p>Pedidos, propostas, pagamentos e conversas com a equipe. Tudo em um só lugar.</p></div><button class="btn orange" data-go="solutions">Explore as soluções ↗</button></div>`;html+=stats([['Meus projetos',state.orders.length,'Pedidos registrados'],['Em desenvolvimento',state.orders.filter(o=>o.phase==='desenvolvimento').length,'Projetos em andamento'],['A pagar',money(payments.filter(p=>['PENDING','OVERDUE'].includes(p.status)).reduce((n,p)=>n+p.value_cents,0)),'Cobranças abertas'],['Entregues',state.orders.filter(o=>o.phase==='entregue').length,'Projetos concluídos']])}html+=`<section class="panel"><div class="panel-head"><h2>Pedidos recentes</h2><button class="btn secondary" data-go="orders">Ver todos ↗</button></div>${admin?orderTable(state.orders.slice(0,6)):clientProjectCards(state.orders.slice(0,3),true)}</section>`}
 if(state.tab==='orders')html=head(admin?'Pedidos e projetos':'Meus pedidos','Abra um pedido para consultar a proposta, o andamento e as mensagens.',admin?'':'<button class="btn orange" id="new-order">Novo projeto +</button>')+`<section class="panel"><div class="panel-head"><h2>${state.orders.length} pedido(s)</h2><input class="search" id="search-orders" aria-label="Buscar pedidos" placeholder="Buscar serviço, cliente ou número"></div><div id="order-results">${orderTable(state.orders)}</div><p class="fine">Exibindo até os 500 pedidos mais recentes.</p></section>`;
 if(state.tab==='finance')html=head(admin?'Financeiro':'Meus pagamentos',admin?'Recebimentos e cobranças dos pedidos do portal.':'Consulte suas cobranças e abra a página de pagamento.',admin?'<a class="btn secondary" href="/api/admin/finance.csv">Exportar CSV ↓</a>':'')+(admin?stats([['Recebido',money(m.received),'Bruto liquidado'],['Confirmado',money(m.confirmed),'Confirmação financeira'],['Pendente',money(m.pending),'Aguardando pagamento'],['Vencido',money(m.overdue),'Em atraso']]):'')+`<section class="panel"><h2>Cobranças</h2>${paymentTable(payments.sort((a,b)=>(b.due_date||'').localeCompare(a.due_date||'')))}</section><p class="fine">Status atualizados por notificações do Asaas. O retorno da página de pagamento não confirma o recebimento. Valores de estorno e contestação permanecem no histórico por status.</p>`;
 if(state.tab==='maintenance'){const orders=state.orders.filter(o=>o.product_id==='site');html=head('Manutenção do seu site','Opcional. R$ 39,90 por mês. Sem modificações.')+`<div class="banner">A primeira cobrança acontece 60 dias após a contratação do site, independentemente de ele já estar no ar. Cobrança recorrente no cartão e cancelamento a seu pedido a qualquer momento.</div>`+orders.map(o=>`<section class="panel"><div class="panel-head"><h2>${escapeHtml(o.title)} · #${o.id.slice(0,8)}</h2>${o.maintenance?badge(o.maintenance.status):'<span class="badge">Não contratada</span>'}</div><p class="muted">${o.maintenance?'Primeiro vencimento: '+date(o.maintenance.first_due):'Você pode autorizar a manutenção após a confirmação do pagamento do site.'}</p><button class="btn secondary" data-order="${o.id}">Ver manutenção ↗</button></section>`).join('')+(!orders.length?'<div class="empty">Nenhum pedido de Site Onepage cadastrado.</div>':'')}
 if(state.tab==='solutions')html=head('Qual é a sua próxima ideia?','Escolha uma solução para começar seu pedido.')+`<div class="service-options">${state.config.products.map((p,i)=>`<article class="service-option"><span class="eyebrow">0${i+1} / Imagine</span><h3>${escapeHtml(p.title)}</h3><p>${p.id==='site'?'Site em página única por R$ 990,00. Manutenção opcional de R$ 39,90/mês, com primeira cobrança após 60 dias da contratação.':'Descreva seu projeto para receber uma proposta personalizada com escopo, prazo e investimento.'}</p><button class="btn" data-new="${p.id}">${p.id==='site'?'Iniciar pedido':'Solicitar proposta'} ↗</button></article>`).join('')}</div>`;
 if(state.tab==='clients')html=head('Clientes','Contas de clientes cadastradas no portal.')+`<section class="panel"><div class="table-wrap"><table><thead><tr><th>Nome</th><th>E-mail</th><th>Cadastro</th><th>Pedidos recentes</th></tr></thead><tbody>${state.admin.clients.map(c=>`<tr><td>${escapeHtml(c.name)}</td><td>${escapeHtml(c.email)}</td><td>${date(c.created_at)}</td><td>${state.orders.filter(o=>o.user_id===c.id).length}</td></tr>`).join('')}</tbody></table></div></section>`;
 if(state.tab==='catalog')html=head('Catálogo e propostas','Defina entregas e prazo antes de liberar a contratação online.')+`<div class="banner">O Site Onepage mantém o valor aprovado de R$ 990,00. Os demais serviços podem receber preços e escopos próprios. Alterações afetam apenas novos pedidos.</div><div class="two-cols">${state.config.products.map(p=>`<form class="panel product-form" data-id="${p.id}"><h2>${escapeHtml(p.title)}</h2><label class="field"><span>Preço em reais</span><input name="price" type="number" min="0.01" step="0.01" value="${p.price_cents?p.price_cents/100:''}" ${p.id==='site'?'readonly':''}></label><label class="field"><span>Escopo, entregas, revisões e exclusões</span><textarea name="scope" maxlength="10000">${escapeHtml(p.scope)}</textarea></label><label class="field"><span>Prazo e condição de início</span><input name="delivery" value="${escapeHtml(p.delivery)}" maxlength="500"></label><label class="checkbox"><input type="checkbox" name="enabled" ${p.enabled?'checked':''}><span>Liberar proposta para novos pedidos</span></label><button class="btn" type="submit">Salvar condições</button></form>`).join('')}</div>`;
 if(state.tab==='activity')html=head('Atividade e conciliação','Histórico administrativo e eventos que precisam de atenção.')+`<section class="panel"><h2>Eventos pendentes</h2>${state.admin.events.length?'<div class="table-wrap"><table><thead><tr><th>Evento</th><th>Recurso</th><th>Tentativas</th><th>Situação</th></tr></thead><tbody>'+state.admin.events.map(e=>`<tr><td>${escapeHtml(e.type)}</td><td>${escapeHtml(e.resource_id)}</td><td>${e.attempts}</td><td>${escapeHtml(e.error||'Aguardando processamento')}</td></tr>`).join('')+'</tbody></table></div>':'<div class="empty">Nenhum evento pendente.</div>'}</section><section class="panel"><h2>Últimas ações</h2><div class="table-wrap"><table><thead><tr><th>Data</th><th>Responsável</th><th>Ação</th><th>Referência</th></tr></thead><tbody>${state.admin.audit.map(a=>`<tr><td>${date(a.created_at)}</td><td>${escapeHtml(a.name||'Operador do servidor')}</td><td>${escapeHtml(a.action)}</td><td>${escapeHtml(a.resource_id?.slice(0,8)||'—')}</td></tr>`).join('')}</tbody></table></div></section>`;
 if(state.tab==='account')html=head('Minha conta','Mantenha seu acesso protegido.')+`<section class="panel account-card"><h2>${escapeHtml(state.user.name)}</h2><p class="muted">${escapeHtml(state.user.email)}</p><hr class="section-divider"><form id="password-form"><h2>Alterar senha</h2><label class="field"><span>Senha atual</span><input name="currentPassword" type="password" autocomplete="current-password" required maxlength="128"></label><label class="field"><span>Nova senha · 12 a 128 caracteres</span><input name="newPassword" type="password" autocomplete="new-password" required minlength="12" maxlength="128"></label><button class="btn" type="submit">Atualizar senha</button></form><p class="fine">Ao alterar sua senha, as outras sessões desta conta serão encerradas.</p></section>`;
 if(state.tab==='overview'&&admin&&!state.user.staff_profile)html=overviewMarkup();if(state.tab==='orders'&&admin)html=ordersOpsMarkup();if(state.tab==='clients')html=clientsMarkup();if(state.tab==='fiscal')html=fiscalMarkup();if(state.tab==='tasks-bi'&&admin&&!state.user.staff_profile)html=tasksBIMarkup();if(state.tab==='bi'&&admin&&!state.user.staff_profile)html=biMarkup();if(state.tab==='finance'&&admin)html=financeDashboard();if(state.tab==='activity'||state.tab==='team')html=teamMarkup(state.tab);if(state.tab==='overview'&&state.user.staff_profile)html=head('Seu espaço de trabalho','Consulte seus pedidos e as atividades atribuídas a você.')+'<button class="btn orange" data-go="activity">Minhas atividades ↗</button>'; if(state.tab==='orders'&&!admin)html=clientOrdersMarkup();if(state.tab==='finance'&&!admin)html=clientFinanceMarkup();if(state.tab==='maintenance'&&!admin)html=clientCareMarkup();view.innerHTML=html;bindView();bindClientOrderButtons();if(state.tab==='orders'&&!admin)bindClientOrders();if(state.tab==='finance'&&!admin)bindClientFinance();if(state.tab==='maintenance'&&!admin)bindClientCare();if(state.tab==='overview'&&admin&&!state.user.staff_profile)loadOverview();if(state.tab==='orders'&&admin)loadOrdersOps();if(state.tab==='clients')loadClients();if(state.tab==='tasks-bi'&&admin&&!state.user.staff_profile)loadTasksBI();if(state.tab==='bi'&&admin&&!state.user.staff_profile)loadBI();if(state.tab==='fiscal')loadFiscal();if(state.tab==='finance'&&admin)bindFinance();if(state.tab==='activity')loadWork();if(state.tab==='team')loadTeam()}
function bindOrderButtons(){document.querySelectorAll('[data-order]').forEach(b=>b.onclick=()=>openOrder(b.dataset.order))}
function bindView(){bindOrderButtons();document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>{state.tab=b.dataset.go;render()});document.querySelectorAll('[data-new]').forEach(b=>b.onclick=()=>newOrder(b.dataset.new));document.querySelector('#new-order')?.addEventListener('click',()=>newOrder());document.querySelector('#refresh')?.addEventListener('click',e=>task(e.currentTarget,async()=>{await load();render();notify('Dados atualizados.')}));document.querySelector('#search-orders')?.addEventListener('input',e=>{const query=e.target.value.toLowerCase();document.querySelector('#order-results').innerHTML=orderTable(state.orders.filter(o=>[o.title,o.id,o.client?.name,o.client?.email].some(v=>v?.toLowerCase().includes(query))));bindOrderButtons()});document.querySelectorAll('.product-form').forEach(form=>form.onsubmit=e=>{e.preventDefault();task(e.submitter,async()=>{const data=Object.fromEntries(new FormData(form));await post('/api/admin/products',{id:form.dataset.id,price_cents:data.price?Math.round(Number(data.price)*100):null,scope:data.scope,delivery:data.delivery,enabled:data.enabled==='on'});await load();render();notify('Condições atualizadas para novos pedidos.')})});document.querySelector('#password-form')?.addEventListener('submit',e=>{e.preventDefault();task(e.submitter,async()=>{const result=await post('/api/password',Object.fromEntries(new FormData(e.target)));state.csrf=result.csrf;e.target.reset();notify('Senha atualizada. Outras sessões foram encerradas.')})})}
function showDialog(html){dialog.classList.remove('client-project-dialog');detail.innerHTML=html;dialog.scrollTop=0;if(!dialog.open)dialog.showModal()}
function newOrder(product='site'){state.requestId=crypto.randomUUID();showDialog(`<span class="eyebrow">Novo projeto</span><h2 id="details-title">Conte sua próxima ideia.</h2><form id="new-order-form"><label class="field"><span>Solução</span><select name="product">${state.config.products.map(p=>`<option value="${p.id}" ${p.id===product?'selected':''}>${escapeHtml(p.title)}</option>`).join('')}</select></label><label class="field"><span>O que sua empresa precisa?</span><textarea name="brief" required minlength="10" maxlength="5000" placeholder="Conte sobre sua empresa, seu objetivo e as funcionalidades que imagina."></textarea></label><p class="fine">Registrar o pedido não gera uma cobrança. Você poderá revisar a proposta antes de contratar.</p><button class="btn orange" type="submit">Registrar meu projeto ↗</button></form>`);document.querySelector('#new-order-form').onsubmit=e=>{e.preventDefault();task(e.submitter,async()=>{const result=await post('/api/orders',{...Object.fromEntries(new FormData(e.target)),requestId:state.requestId});await load();state.tab='orders';render();await openOrder(result.order.id);notify('Pedido registrado. Vamos construir seu próximo passo.')})}}
async function openOrder(id,focus='journey'){try{const {order:o}=await api('/api/orders/'+id);state.selected=id;const admin=state.user.role==='admin',paid=['CONFIRMED','RECEIVED','RECEIVED_IN_CASH'].includes(o.payment_status),m=o.maintenance;let html=`<span class="eyebrow">Pedido #${o.id.slice(0,8)} · ${date(o.created_at)}</span><h2 id="details-title">${escapeHtml(o.title)}</h2><div class="detail-meta">${badge(o.phase)} ${badge(o.payment_status)}</div>${admin?`<p class="fine">Cliente: ${escapeHtml(o.client.name)} · ${escapeHtml(o.client.email)}</p>`:''}${!admin?'<section id="client-commercial">':''}<h3>Sobre o projeto</h3><div class="detail-text">${escapeHtml(o.brief)}</div><h3>Proposta · versão ${o.terms_version}</h3><div class="detail-text">${escapeHtml(o.scope||'Nossa equipe está preparando o escopo para você.')}</div><p class="fine">Prazo: ${escapeHtml(o.delivery||'A definir na proposta.')}</p><div class="detail-price"><span>Investimento no projeto</span><strong>${o.price_cents?money(o.price_cents):'Sob proposta'}</strong></div>`;
 if(o.billing_state==='uncertain')html+='<div class="banner">A operação financeira está em conciliação. Não crie outro pagamento. A equipe verificará o resultado no Asaas.</div>';
 if(!admin&&!o.payment_id&&o.price_cents&&o.scope&&o.delivery&&o.billing_state==='idle')html+=`<form id="checkout-form"><label class="field"><span>CPF ou CNPJ do pagador</span><input name="cpfCnpj" inputmode="numeric" required maxlength="18" autocomplete="off"></label><p class="fine">Seu documento será enviado ao Asaas para gerar a cobrança deste pedido. Dados do cartão serão preenchidos na página do Asaas.</p><label class="checkbox"><input type="checkbox" name="accepted" required><span>Li e aceito a proposta versão ${o.terms_version}, incluindo escopo, valor e prazo. ${state.config.seller.name?'Prestador: '+escapeHtml(state.config.seller.name)+' · '+escapeHtml(state.config.seller.document)+'.':''}</span></label>${o.product_id==='site'?'<label class="checkbox"><input type="checkbox" name="maintenance"><span>Tenho interesse na manutenção opcional de R$ 39,90/mês, sem modificações. A primeira cobrança será 60 dias após a contratação, mesmo que o site ainda não esteja no ar. Autorizarei o cartão separadamente no Asaas e poderei solicitar cancelamento a qualquer momento.</span></label>':''}<button class="btn orange" type="submit" ${!state.config.billingReady?'disabled':''}>Gerar meu pagamento no Asaas ↗</button></form>`;
 if(o.invoice_url&&!paid&&['PENDING','OVERDUE'].includes(o.payment_status))html+=externalLink(o.invoice_url,'Abrir pagamento do projeto','btn orange');
 if(o.product_id==='site'){html+=`<section class="maintenance-box"><h3>Manutenção opcional · R$ 39,90/mês</h3><p>Primeira cobrança 60 dias após a contratação, independentemente de o site já estar no ar. Inclui hospedagem, recorrente no cartão, sem modificações e cancelável a pedido a qualquer momento.</p>${m?`<p>${badge(m.status)} · Primeiro vencimento: ${date(m.first_due)}</p>`:''}`;if(!admin&&paid&&!m)html+='<form id="maintenance-form"><label class="checkbox"><input type="checkbox" required><span>Quero contratar a manutenção e autorizo as condições acima. Vou informar meu cartão no Asaas.</span></label><button class="btn orange" type="submit">Autorizar manutenção no Asaas ↗</button></form>';if(m?.status==='checkout'&&!admin)html+=externalLink(m.checkout_url,'Continuar autorização no Asaas');if(m&&!['canceled','expired'].includes(m.status))html+='<button class="btn danger" id="cancel-maintenance" type="button">Solicitar cancelamento da manutenção</button>';if(!paid&&!m)html+='<p class="fine">A autorização ficará disponível após a confirmação do pagamento do site.</p>';html+='</section>'}
 html+='<div class="row-buttons"><button class="btn secondary" id="sync-order">Sincronizar com Asaas ↻</button></div>';
 if(admin){html+=`<hr class="section-divider"><h3>Gestão do projeto</h3><form id="phase-form" ${o.product_id==='site'?'hidden':''}><label class="field"><span>Etapa atual</span><select name="phase">${['solicitado','planejamento','desenvolvimento','revisao','entregue'].map(p=>`<option value="${p}" ${o.phase===p?'selected':''}>${statusLabels[p]}</option>`).join('')}</select></label><button class="btn secondary" type="submit">Atualizar etapa</button></form>`;if(!o.accepted_at&&o.billing_state==='idle'&&!o.payment_id)html+=`<h3>Enviar ou atualizar proposta</h3><form id="proposal-form"><label class="field"><span>Valor em reais</span><input name="price" type="number" min="0.01" step="0.01" required value="${o.price_cents?o.price_cents/100:''}"></label><label class="field"><span>Escopo, entregas, revisões, exclusões e condições</span><textarea name="scope" required minlength="20" maxlength="10000">${escapeHtml(o.scope)}</textarea></label><label class="field"><span>Prazo e condição de início</span><input name="delivery" required value="${escapeHtml(o.delivery)}" maxlength="500"></label><button class="btn" type="submit">Salvar proposta para o cliente</button></form>`;if(o.billing_state==='uncertain'&&!o.payment_id)html+='<h3>Revisão manual da cobrança</h3><form id="release-form"><label class="checkbox"><input type="checkbox" required><span>Verifiquei o pedido no painel Asaas e confirmei que nenhuma cobrança foi criada. Autorizo uma nova tentativa.</span></label><button class="btn danger" type="submit">Liberar nova tentativa</button></form>'}
 if(!admin)html+='</section>';html+=productionMarkup(o,admin,paid);html+=onepageBriefingMarkup(o,admin,paid);
 html+=`<hr class="section-divider"><h3>Conversa sobre o pedido</h3><div class="message-list">${o.messages.length?o.messages.map(message=>`<article class="message ${message.role==='admin'?'admin':''}"><header><span>${escapeHtml(message.name)}${message.role==='admin'?' · Imagine':''}</span><time>${date(message.created_at)}</time></header><p>${escapeHtml(message.body)}</p></article>`).join(''):'<p class="fine">Use este espaço para alinhar detalhes com nossa equipe.</p>'}</div><form id="message-form"><label class="field"><span>Nova mensagem</span><textarea name="body" required maxlength="4000"></textarea></label><button class="btn secondary" type="submit">Enviar mensagem</button></form>`;const refreshOrder=async()=>{await load();render();await openOrder(id)};html+=complaintsMarkup(o);showDialog(html);bindComplaints(o,refreshOrder);if(state.user.staff_profile){for(const id of ['proposal-form','release-form','phase-form'])document.getElementById(id)?.remove();if(state.user.staff_profile!=='producao')document.getElementById('production-admin')?.remove();if(state.user.staff_profile==='financeiro')document.querySelector('.briefing-panel')?.remove();else{document.querySelector('.maintenance-box')?.remove();document.getElementById('sync-order')?.remove();document.querySelector('.detail-price')?.remove();}}
 const refresh=async()=>{await load();render();await openOrder(id)};
 bindOnepageBriefing(o,admin,paid,refresh);bindProduction(o,refresh);if(!admin&&o.product_id==='site')enhanceClientOrder(o,focus);
 document.querySelector('#checkout-form')?.addEventListener('submit',e=>{e.preventDefault();task(e.submitter,async()=>{const d=Object.fromEntries(new FormData(e.target));const result=await post('/api/orders/'+id+'/checkout',{cpfCnpj:d.cpfCnpj,accepted:d.accepted==='on',maintenance:d.maintenance==='on',termsVersion:o.terms_version});await refresh();notify('Cobrança criada. Abra o pagamento do projeto para continuar no Asaas.');if(result.invoiceUrl&&!externalLink(result.invoiceUrl,'Pagar'))notify('Confira o pagamento com nossa equipe.',true)})});
 document.querySelector('#maintenance-form')?.addEventListener('submit',e=>{e.preventDefault();task(e.submitter,async()=>{await post('/api/orders/'+id+'/maintenance',{accepted:true});await refresh();notify('Checkout criado. Continue a autorização do cartão no Asaas.')})});
 document.querySelector('#cancel-maintenance')?.addEventListener('click',e=>{if(!confirm('Deseja solicitar o cancelamento da manutenção mensal deste pedido?'))return;task(e.currentTarget,async()=>{await post('/api/orders/'+id+'/cancel-maintenance');await refresh();notify('Manutenção cancelada. Consulte o histórico de cobranças.')})});
 if(document.querySelector('#sync-order'))document.querySelector('#sync-order').onclick=e=>task(e.currentTarget,async()=>{await post('/api/orders/'+id+'/sync');await refresh();notify('Conciliação concluída.')});
 document.querySelector('#message-form').onsubmit=e=>{e.preventDefault();task(e.submitter,async()=>{await post('/api/orders/'+id+'/messages',Object.fromEntries(new FormData(e.target)));await refresh();notify('Mensagem enviada.')})};
 document.querySelector('#phase-form')?.addEventListener('submit',e=>{e.preventDefault();task(e.submitter,async()=>{await post('/api/orders/'+id+'/phase',Object.fromEntries(new FormData(e.target)));await refresh();notify('Etapa atualizada.')})});
 document.querySelector('#proposal-form')?.addEventListener('submit',e=>{e.preventDefault();task(e.submitter,async()=>{const d=Object.fromEntries(new FormData(e.target));await post('/api/orders/'+id+'/proposal',{price_cents:Math.round(Number(d.price)*100),scope:d.scope,delivery:d.delivery});await refresh();notify('Proposta disponível para o cliente.')})});
 document.querySelector('#release-form')?.addEventListener('submit',e=>{e.preventDefault();task(e.submitter,async()=>{await post('/api/orders/'+id+'/release-billing',{reviewedNoCharge:true});await refresh();notify('Nova tentativa liberada após revisão.')})});
 }catch(error){notify(error.message,true)}}
document.querySelector('.dialog-close').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
async function init(){if(location.protocol==='file:'){app.innerHTML='<div class="auth-form"><img class="logo" src="assets/logo-imagine.png" alt="Imagine Comunicação Digital"><h2>Seu portal está preparado.</h2><p>Login, pedidos e pagamentos precisam ser executados pelo servidor da aplicação.</p><p>Abra o endereço do portal após a instalação no servidor. Esta cópia de arquivo não conecta ao banco de dados nem ao Asaas.</p><a class="btn" href="index.html">Voltar ao site</a></div>';return}try{state.config=await api('/api/config');const result=await api('/api/session');state.user=result.user;state.csrf=result.csrf||'';if(state.user){await load();render();const requested=new URLSearchParams(location.search).get('product');if(requested&&state.user.role==='client')newOrder(requested)}else renderAuth()}catch(error){app.innerHTML='<div class="auth-form"><h2>Não foi possível acessar o portal.</h2><p>'+escapeHtml(error.message)+'</p><a class="btn" href="/">Voltar ao site</a></div>'}}init();

const financeFilters={from:'',to:'',kind:'',status:'',query:''};
function financeRows(){return state.orders.flatMap(o=>o.payments.map(p=>({...p,order:o})));}
function filteredFinance(){const f=financeFilters;return financeRows().filter(p=>{const d=(['RECEIVED','RECEIVED_IN_CASH'].includes(p.status)?p.paid_at:p.due_date)?.slice(0,10)||'';return (!f.from||d>=f.from)&&(!f.to||d&&d<=f.to)&&(!f.kind||p.kind===f.kind)&&(!f.status||p.status===f.status)&&(!f.query||[p.order.title,p.order.client?.name,p.order.client?.email,p.order_id].join(' ').toLowerCase().includes(f.query.toLowerCase()));});}
function financeDashboard(){return head('Seu financeiro, em perspectiva.','Implantações, assinaturas e recebimentos em um só lugar.','<button class="btn secondary" id="finance-export">Exportar seleção CSV ↓</button>')+`<section class="panel finance-filter"><form id="finance-filters"><label>De<input name="from" type="date" value="${financeFilters.from}"></label><label>Até<input name="to" type="date" value="${financeFilters.to}"></label><label>Tipo<select name="kind"><option value="">Todos</option><option value="site">Implantação / projeto</option><option value="maintenance">Assinatura</option></select></label><label>Situação<select name="status"><option value="">Todas</option>${['RECEIVED','CONFIRMED','PENDING','OVERDUE','REFUNDED','DELETED'].map(s=>`<option value="${s}">${statusLabels[s]}</option>`).join('')}</select></label><label>Cliente ou pedido<input name="query" placeholder="Buscar empresa, cliente…" value="${escapeHtml(financeFilters.query)}"></label><button class="btn orange">Aplicar filtros</button><button class="btn secondary" type="button" id="finance-clear">Limpar</button></form><p class="fine">Período: data do recebimento para valores liquidados e vencimento para as demais cobranças. Sem filtro: todos os registros carregados.</p></section><div id="finance-results"></div>`;}
function financeResults(){const rows=filteredFinance(),received=rows.filter(p=>['RECEIVED','RECEIVED_IN_CASH'].includes(p.status)),sum=items=>items.reduce((s,p)=>s+p.value_cents,0),pending=rows.filter(p=>p.status==='PENDING'),overdue=rows.filter(p=>p.status==='OVERDUE'),known=received.filter(p=>p.net_cents!==null),net=known.reduce((s,p)=>s+p.net_cents,0);const orders=state.orders.filter(o=>o.product_id==='site'),active=orders.filter(o=>o.maintenance?.status==='active'&&!o.maintenance.cancel_requested_at),scheduled=orders.filter(o=>o.maintenance?.status==='checkout'),canceling=orders.filter(o=>o.maintenance?.cancel_requested_at&&!o.maintenance.canceled_at);const today=new Date().toLocaleDateString('en-CA',{timeZone:'America/Sao_Paulo'});const daysUntil=d=>Math.round((new Date(d+'T12:00:00Z')-new Date(today+'T12:00:00Z'))/86400000);const forecast=[30,60,90].map(n=>sum(rows.filter(p=>['PENDING','CONFIRMED'].includes(p.status)&&p.due_date&&daysUntil(p.due_date)>=0&&daysUntil(p.due_date)<=n)));
const monthly=new Map();for(const p of received){const key=p.paid_at?.slice(0,7);if(!key)continue;if(!monthly.has(key))monthly.set(key,{site:0,maintenance:0});monthly.get(key)[p.kind==='maintenance'?'maintenance':'site']+=p.value_cents;}const months=[...monthly.entries()].sort(([a],[b])=>a.localeCompare(b)).slice(-6),max=Math.max(1,...months.map(([,v])=>v.site+v.maintenance));
const subs=active.map(o=>{const last=o.payments.filter(p=>p.kind==='maintenance'&&!['DELETED','REFUNDED'].includes(p.status)).sort((a,b)=>(b.due_date||'').localeCompare(a.due_date||''))[0];return last?.value_cents;}),mrr=subs.length&&subs.every(v=>Number.isInteger(v))?subs.reduce((a,b)=>a+b,0):null;
document.querySelector('#finance-results').innerHTML=`<div class="stats finance-stats">${[['Recebido bruto',money(sum(received)),`${received.length} cobrança(s) liquidada(s)`],['Líquido informado',money(net),known.length===received.length?'Após taxas informadas pelo Asaas':`${received.length-known.length} recebimento(s) sem líquido informado`],['A receber',money(sum(pending)),'Cobranças pendentes no período'],['Em atraso',money(sum(overdue)),`${overdue.length} cobrança(s) requerem atenção`]].map(([a,b,c],i)=>`<article class="stat ${i===0?'finance-primary':i===3?'finance-danger':''}"><span class="stat-label">${a}</span><strong>${b}</strong><small>${c}</small></article>`).join('')}</div><div class="finance-grid"><section class="panel"><div class="panel-head"><h2>Evolução dos recebimentos</h2><span class="fine">Últimos 6 meses com recebimentos no filtro</span></div><div class="finance-legend"><span>● Implantação / projeto</span><span>● Assinatura</span></div>${months.length?months.map(([month,v])=>`<div class="finance-chart-row"><span>${month.split('-').reverse().join('/')}</span><div class="finance-track"><i style="width:${100*v.site/max}%"></i><i class="recurring" style="width:${100*v.maintenance/max}%"></i></div><strong>${money(v.site+v.maintenance)}</strong></div>`).join(''):'<div class="empty">Sem recebimentos com data registrada neste período.</div>'}<p class="fine">Valores brutos efetivamente recebidos. Confirmados ainda não são recebimentos.</p></section><section class="panel finance-forecast"><h2>Previsão de entrada</h2><p class="fine">Cobranças já geradas, nos filtros selecionados. Valores cumulativos, sem garantia de recebimento.</p>${[30,60,90].map((n,i)=>`<div><span>Próximos ${n} dias</span><strong>${money(forecast[i])}</strong></div>`).join('')}<p class="fine">Confirmado no período: ${money(sum(rows.filter(p=>p.status==='CONFIRMED')))}. Vencidos ficam fora da previsão.</p></section></div><section class="panel"><div class="panel-head"><h2>Carteira de assinaturas</h2><span class="fine">Situação atual de todos os pedidos carregados · independente dos filtros de cobrança</span></div><div class="finance-subscriptions">${[['Ativas',active.length],['Em autorização',scheduled.length],['Cancelamento solicitado',canceling.length],['Sem assinatura cadastrada',orders.filter(o=>!o.maintenance).length]].map(([a,b])=>`<div><strong>${b}</strong><span>${a}</span></div>`).join('')}<div><strong>${mrr===null?'—':money(mrr)}</strong><span>Recorrência mensal estimada</span></div></div><p class="fine">Estimativa baseada na última cobrança de cada assinatura ativa; não equivale a dinheiro recebido. Sem valores cadastrados, a estimativa não é exibida. A oferta de R$ 79,90 após 90 dias ainda precisa ser integrada à cobrança; não projetamos contratos inexistentes.</p></section><section class="panel"><div class="panel-head"><h2>Precisam de atenção</h2><span class="badge bad">${overdue.length} cobrança(s) vencida(s)</span></div>${overdue.length?overdue.map(p=>`<div class="finance-alert"><div><strong>${escapeHtml(p.order.title)}</strong><small>${escapeHtml(p.order.client?.name||'')} · Venceu em ${date(p.due_date)}</small></div><strong>${money(p.value_cents)}</strong><button class="btn secondary" data-order="${p.order_id}">Ver pedido ↗</button>${collectionButton(p)}</div>`).join(''):'<p class="muted">Nenhuma cobrança vencida nos filtros selecionados.</p>'}</section><section class="panel"><div class="panel-head"><h2>Detalhamento das cobranças</h2><span class="fine">${rows.length} registro(s)</span></div><div class="table-wrap"><table><thead><tr><th>Empresa / pedido</th><th>Tipo / parcela</th><th>Bruto</th><th>Líquido</th><th>Vencimento</th><th>Recebimento</th><th>Situação</th><th></th></tr></thead><tbody>${rows.sort((a,b)=>(b.due_date||'').localeCompare(a.due_date||'')).map(p=>{const installments=p.order.payments.filter(x=>x.kind===p.kind).sort((a,b)=>(a.due_date||'').localeCompare(b.due_date||'')||a.id.localeCompare(b.id));return `<tr><td><strong>${escapeHtml(p.order.title)}</strong><small>${escapeHtml(p.order.client?.name||'')} · #${p.order_id.slice(0,8)}</small></td><td>${p.kind==='maintenance'?'Assinatura':'Implantação / projeto'}<small>${p.kind==='maintenance'?'Mensalidade':`Cobrança ${installments.findIndex(x=>x.id===p.id)+1} de ${installments.length} cadastradas`}</small></td><td>${money(p.value_cents)}</td><td>${p.net_cents===null?'—':money(p.net_cents)}</td><td>${date(p.due_date)}</td><td>${date(p.paid_at)}</td><td>${badge(p.status)}</td><td><button class="btn secondary" data-order="${p.order_id}">Ver pedido ↗</button>${collectionButton(p)}</td></tr>`;}).join('')}</tbody></table></div>${!rows.length?'<div class="empty">Nenhuma cobrança corresponde aos filtros.</div>':''}</section><p class="fine">Visão dos pedidos carregados pelo portal (até 500). Não representa o saldo bancário, lucro ou todas as movimentações do Asaas. Falhas de cartão só poderão ser destacadas quando esses eventos forem integrados.</p>`;bindOrderButtons();bindCollections();}
function bindFinance(){const form=document.querySelector('#finance-filters');if(!form)return;form.elements.kind.value=financeFilters.kind;form.elements.status.value=financeFilters.status;form.onsubmit=e=>{e.preventDefault();const f=Object.fromEntries(new FormData(form));if(f.from&&f.to&&f.from>f.to)return notify('A data inicial deve ser anterior à final.',true);Object.assign(financeFilters,f);financeResults();};document.querySelector('#finance-clear').onclick=()=>{Object.assign(financeFilters,{from:'',to:'',kind:'',status:'',query:''});renderView();};document.querySelector('#finance-export').onclick=()=>{const cell=v=>'"'+String(v??'').replace(/^[=+@\-\t\r]/,"' $&").replaceAll('"','""')+'"',rows=[['Empresa / pedido','Cliente','Tipo','Status','Bruto BRL','Líquido BRL','Vencimento','Recebimento'],...filteredFinance().map(p=>[p.order.title,p.order.client?.name,p.kind,p.status,(p.value_cents/100).toFixed(2),p.net_cents===null?'':(p.net_cents/100).toFixed(2),p.due_date,p.paid_at])],url=URL.createObjectURL(new Blob(['\uFEFF'+rows.map(r=>r.map(cell).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='financeiro-imagine-filtrado.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};financeResults();}

function teamMarkup(tab){return head(tab==='team'?'Equipe e acessos':'Central de atividades',tab==='team'?'Cadastre colaboradores e defina o que cada função pode acessar.':'Responsáveis, prazos e tarefas geradas pela evolução dos pedidos.','<button class="btn secondary" id="team-refresh">Atualizar ↻</button>')+'<div id="team-content" aria-live="polite">Carregando…</div>';}
async function loadTeam(){try{const d=await api('/api/team/tasks'),box=document.querySelector('#team-content');if(!box)return;const manager=!state.user.staff_profile,labels={pending:'A fazer',doing:'Em andamento',blocked:'Bloqueada',done:'Concluída'},options=(selected,empty=true)=>(empty?'<option value="">Sem responsável</option>':'')+d.members.filter(m=>m.active).map(m=>`<option value="${m.id}" ${m.id===selected?'selected':''}>${escapeHtml(m.name)} · ${d.profiles[m.profile].label}</option>`).join('');
if(state.tab==='team'){box.innerHTML=`<div class="banner">Administrador: acesso completo. Atendimento: pedidos, materiais, clientes e mensagens. Produção: pedidos com atividades atribuídas, evolução e prévias. Financeiro: pedidos e cobranças. Somente o administrador gerencia equipe, regras e acessos. Colaboradores não cadastram outros usuários.</div><section class="panel"><h2>Novo colaborador</h2><form id="team-create" class="team-form"><label class="field"><span>Nome completo</span><input name="name" required maxlength="120"></label><label class="field"><span>E-mail</span><input name="email" type="email" required maxlength="254"></label><label class="field"><span>Função</span><select name="profile">${Object.entries(d.profiles).map(([k,v])=>`<option value="${k}">${v.label}</option>`).join('')}</select></label><label class="field"><span>Senha inicial · mínimo 12 caracteres</span><input name="password" type="password" autocomplete="new-password" minlength="12" maxlength="128" required></label><button class="btn orange">Cadastrar colaborador</button></form><p class="fine">O acesso é criado no portal. Combine a entrega da senha inicial com o colaborador; ele poderá alterá-la em Minha conta. Não há envio automático de convite por e-mail nesta versão.</p></section><section class="panel"><h2>Colaboradores cadastrados</h2>${d.members.length?d.members.map(m=>`<form class="member-form toolbar" data-id="${m.id}"><strong>${escapeHtml(m.name)}<small class="muted"> · ${escapeHtml(m.email)}</small></strong><label>Função<select name="profile">${Object.entries(d.profiles).map(([k,v])=>`<option value="${k}" ${k===m.profile?'selected':''}>${v.label}</option>`).join('')}</select></label><label>Status<select name="active"><option value="true" ${m.active?'selected':''}>Ativo</option><option value="false" ${!m.active?'selected':''}>Desativado</option></select></label><button class="btn secondary">Salvar acesso</button></form>`).join(''):'<div class="empty">Nenhum colaborador cadastrado.</div>'}<p class="fine">Alterar função ou desativar encerra as sessões do colaborador. Tarefas abertas permanecem no histórico e devem ser reatribuídas pelo administrador.</p></section><section class="panel"><h2>Distribuição automática de atividades</h2><p class="fine">Defina um responsável por tipo. Prazo em dias corridos a partir da criação da tarefa; não altera o prazo comercial do site. Salvar uma regra também atribui tarefas abertas deste tipo que estejam sem responsável.</p>${d.rules.map(r=>`<form class="rule-form toolbar" data-kind="${r.kind}"><strong>${d.kinds[r.kind]}</strong><label>Responsável<select name="assignee_id">${options(r.assignee_id)}</select></label><label>Prazo (dias)<input name="days" type="number" min="0" max="90" value="${r.days}" required></label><button class="btn secondary">Salvar regra</button></form>`).join('')}</section>`;
document.querySelector('#team-create').onsubmit=e=>{e.preventDefault();task(e.submitter,async()=>{await post('/api/team/tasks',{action:'create-user',...Object.fromEntries(new FormData(e.target))});await loadTeam();notify('Colaborador cadastrado.');})};document.querySelectorAll('.member-form').forEach(f=>f.onsubmit=e=>{e.preventDefault();task(e.submitter,async()=>{const v=Object.fromEntries(new FormData(f));await post('/api/team/tasks',{action:'update-user',id:f.dataset.id,profile:v.profile,active:v.active==='true'});await loadTeam();notify('Acesso atualizado e sessões encerradas.');})});document.querySelectorAll('.rule-form').forEach(f=>f.onsubmit=e=>{e.preventDefault();task(e.submitter,async()=>{await post('/api/team/tasks',{action:'rule',kind:f.dataset.kind,...Object.fromEntries(new FormData(f))});await loadTeam();notify('Regra de distribuição salva.');})});
}else{const today=new Date().toLocaleDateString('en-CA',{timeZone:'America/Sao_Paulo'}),open=d.tasks.filter(t=>!['done','canceled'].includes(t.status)&&!t.archived_at);box.innerHTML=stats([['A fazer',open.filter(t=>t.status==='pending').length,'Tarefas aguardando início'],['Em andamento',open.filter(t=>t.status==='doing').length,'Trabalho em execução'],['Em atraso',open.filter(t=>t.due_date<today).length,'Prazo da atividade vencido'],['Sem responsável',open.filter(t=>!t.assignee_id).length,'Aguardando distribuição']])+`<div class="toolbar"><label>Visualizar<select id="task-filter"><option value="open">Atividades abertas</option><option value="all">Todas, incluindo concluídas</option><option value="mine">Atribuídas a mim</option><option value="unassigned">Sem responsável</option></select></label>${manager?'<button class="btn secondary" data-go="team">Equipe e regras ↗</button>':''}</div><div class="banner">As tarefas são criadas automaticamente a cada 30 segundos enquanto o servidor está ativo e também ao abrir esta tela. Cada evento gera uma única tarefa. Quando a etapa correspondente é concluída no pedido, a atividade é encerrada automaticamente. ${manager?'Configure a equipe para distribuir os novos trabalhos.':'Você visualiza somente atividades atribuídas a você.'}</div><div id="task-list"></div>`;
const draw=()=>{const filter=document.querySelector('#task-filter').value,rows=d.tasks.filter(t=>filter==='all'||filter==='open'&&t.status!=='done'||filter==='mine'&&t.assignee_id===state.user.id||filter==='unassigned'&&!t.assignee_id&&t.status!=='done');document.querySelector('#task-list').innerHTML=rows.length?rows.map(t=>`<article class="panel task-card"><div class="panel-head"><div><span class="eyebrow">${t.source_key?'Automática':'Manual'} · ${escapeHtml(d.kinds[t.kind])}</span><h2>${escapeHtml(t.title)}</h2><p>${escapeHtml(t.order_title)}</p></div><span class="badge ${t.status==='done'?'good':t.due_date<today?'bad':'warn'}">${labels[t.status]}</span></div><p class="fine">Responsável: ${escapeHtml(t.assignee||'Sem responsável')} · Prazo: ${date(t.due_date)} · Criada em ${date(t.created_at)}</p><form class="task-update" data-id="${t.id}"><div class="team-form"><label class="field"><span>Situação</span><select name="status">${Object.entries(labels).map(([k,v])=>`<option value="${k}" ${t.status===k?'selected':''}>${v}</option>`).join('')}</select></label>${manager?`<label class="field"><span>Responsável</span><select name="assignee_id">${options(t.assignee_id)}</select></label>`:''}</div><label class="field"><span>Observação desta atualização</span><textarea name="note" required maxlength="4000" placeholder="Descreva o andamento, impedimento ou conclusão."></textarea></label>${t.note?`<p class="fine">Última observação: ${escapeHtml(t.note)}</p>`:''}<details><summary>Histórico de atualizações</summary>${t.updates?.length?t.updates.map(h=>`<article class="message"><header>${escapeHtml(h.name)} · ${date(h.created_at)} · ${labels[h.status]}</header><p>${escapeHtml(h.note)}</p></article>`).join(''):'<p class="fine">Ainda sem atualizações manuais.</p>'}</details><div class="row-buttons"><button class="btn secondary" type="button" data-order="${t.order_id}">Abrir pedido ↗</button><button class="btn orange">Registrar atualização</button></div></form></article>`).join(''):'<div class="panel empty">Nenhuma atividade nesta visualização.</div>';bindOrderButtons();document.querySelectorAll('.task-update').forEach(f=>f.onsubmit=e=>{e.preventDefault();task(e.submitter,async()=>{await post('/api/team/tasks',{id:f.dataset.id,version:d.tasks.find(t=>t.id===f.dataset.id).version,...Object.fromEntries(new FormData(f))});await loadTeam();notify('Atividade atualizada.');})});};document.querySelector('#task-filter').onchange=draw;document.querySelector('[data-go="team"]')?.addEventListener('click',()=>{state.tab='team';renderView()});draw();}
document.querySelector('#team-refresh').onclick=()=>loadTeam();}catch(e){notify(e.message,true);}}

function biMarkup(){return head('Visão estratégica da Imagine.','Decisões com base em vendas, recebimentos e operação.','<button class="btn secondary" id="bi-refresh">Atualizar dados ↻</button>')+`<section class="panel finance-filter"><form id="bi-filters"><label>De<input name="from" type="date"></label><label>Até<input name="to" type="date"></label><label>Serviço<select name="product"><option value="">Todos os serviços</option>${state.config.products.map(p=>`<option value="${p.id}">${escapeHtml(p.title)}</option>`).join('')}</select></label><button class="btn orange">Analisar período</button></form><p class="fine">Recebimentos pela data de pagamento; cobranças pelo vencimento; vendas pela contratação ou criação do pedido. Operação e assinaturas mostram a situação atual.</p></section><div id="bi-content" aria-live="polite">Carregando indicadores…</div>`;}
async function loadBI(params=''){const box=document.querySelector('#bi-content');if(!box)return;try{const d=await api('/api/admin/bi?'+params);if(!document.querySelector('#bi-content'))return;const f=document.querySelector('#bi-filters');f.elements.from.value=d.from;f.elements.to.value=d.to;f.elements.product.value=d.product;f.onsubmit=e=>{e.preventDefault();loadBI(new URLSearchParams(new FormData(f)).toString())};document.querySelector('#bi-refresh').onclick=()=>loadBI(new URLSearchParams(new FormData(f)).toString());const s=d.summary,op=d.operations,sub=d.subscriptions,bar=(items,value,label,formatter=money)=>{const max=Math.max(1,...items.map(value));return items.length?items.map(x=>`<div class="bi-bar-row"><div><span>${escapeHtml(label(x))}</span><strong>${formatter(value(x))}</strong></div><svg viewBox="0 0 500 13" preserveAspectRatio="none" role="img" aria-label="${escapeHtml(label(x))}: ${formatter(value(x))}"><rect width="500" height="13" rx="4" fill="#f1f1f1"/><rect width="${500*value(x)/max}" height="13" rx="4" fill="#f9941d"/></svg></div>`).join(''):'<p class="muted">Sem registros no período.</p>';},labels={preparation:'Materiais / preparação',production:'Em produção',changes:'Ajustes',review:'Revisão do cliente',approved:'Aprovado para publicar',published:'Publicado'};
const max=Math.max(1,...d.months.map(m=>m.project+m.recurring)),chart=d.months.map((m,i)=>{const x=20+i*65,h1=150*m.project/max,h2=150*m.recurring/max;return `<g><title>${m.month}: projetos ${money(m.project)}, assinaturas ${money(m.recurring)}</title><rect x="${x}" y="${165-h1}" width="35" height="${h1}" rx="3" fill="#f9941d"/><rect x="${x}" y="${165-h1-h2}" width="35" height="${h2}" fill="#426d59"/><text x="${x+17}" y="188" text-anchor="middle" font-size="10" fill="#737373">${m.month.slice(5)}/${m.month.slice(2,4)}</text></g>`}).join('');
box.innerHTML=`<div class="bi-context"><span class="badge">${date(d.from)} a ${date(d.to)}</span><span class="fine">Atualizado em ${new Date(d.generated_at).toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo'})} · Fonte: banco de dados do portal</span></div><div class="stats"><article class="stat finance-primary"><span class="stat-label">Recebido no período</span><strong>${money(s.received)}</strong><small>${s.change_percent===null?'Sem base de recebimentos no período anterior':`${s.change_percent>0?'+':''}${s.change_percent}% versus período anterior de mesma duração`}</small></article><article class="stat"><span class="stat-label">Líquido informado</span><strong>${money(s.net)}</strong><small>${s.net_missing?`${s.net_missing} recebimento(s) sem valor líquido`:`Taxas informadas: ${money(s.fees)}`}</small></article><article class="stat"><span class="stat-label">Contratado no período</span><strong>${money(s.contracted)}</strong><small>${s.accepted} contratação(ões) registrada(s) · não é recebimento</small></article><article class="stat finance-danger"><span class="stat-label">Cobranças vencidas</span><strong>${money(s.overdue)}</strong><small>Vencimentos dentro do período selecionado</small></article></div><div class="bi-mini"><div><strong>${s.orders}</strong><span>Pedidos no período</span></div><div><strong>${s.paying_customers}</strong><span>Clientes com recebimento</span></div><div><strong>${s.average_payment===null?'—':money(s.average_payment)}</strong><span>Valor médio por recebimento</span></div><div><strong>${sub.active}</strong><span>Assinaturas ativas hoje</span></div></div><div class="finance-grid"><section class="panel"><div class="panel-head"><h2>Evolução da receita recebida</h2><span class="fine">Valores brutos</span></div><div class="finance-legend"><span>● Projetos / implantação</span><span>● Assinatura</span></div><div class="bi-chart"><svg viewBox="0 0 ${Math.max(390,d.months.length*65+20)} 200" role="img" aria-label="Recebimentos por mês, separados entre projetos e assinaturas"><line x1="0" y1="165" x2="${Math.max(390,d.months.length*65+20)}" y2="165" stroke="#ddd"/>${chart}</svg></div><details><summary>Ver valores do gráfico</summary><div class="table-wrap"><table><thead><tr><th>Mês</th><th>Projetos</th><th>Assinaturas</th><th>Total</th></tr></thead><tbody>${d.months.map(m=>`<tr><td>${m.month}</td><td>${money(m.project)}</td><td>${money(m.recurring)}</td><td>${money(m.project+m.recurring)}</td></tr>`).join('')}</tbody></table></div></details></section><section class="panel"><h2>Receita por serviço</h2>${bar(d.products,x=>x.received,x=>x.title)}<p class="fine">Qual serviço está contribuindo mais para os recebimentos neste período?</p></section></div><div class="finance-grid"><section class="panel"><h2>Saúde da operação · agora</h2>${bar(op.stages,x=>x.count,x=>labels[x.stage],x=>String(x))}<p class="fine">Distribuição atual dos Onepages com jornada cadastrada. Não é um funil de leads nem uma taxa de conversão.</p></section><section class="panel"><h2>Receita futura e recorrência</h2><div class="bi-measure"><span>Recorrência mensal estimada</span><strong>${sub.monthly_estimate===null?'Sem base suficiente':money(sub.monthly_estimate)}</strong></div><p class="fine">Base: última cobrança cadastrada de cada assinatura ativa. Não soma assinaturas ainda não iniciadas nem representa recebimento garantido.</p>${d.forecast.map(v=>`<div class="bi-measure"><span>Próximos ${v.days} dias</span><strong>${money(v.value)}</strong></div>`).join('')}<p class="fine">Previsão cumulativa de cobranças pendentes ou confirmadas já geradas, para o serviço selecionado; independente do período histórico. Vencidos são excluídos.</p><div class="bi-measure"><span>Cancelamentos solicitados</span><strong>${sub.cancel_requests}</strong></div></section></div><section class="panel"><div class="panel-head"><h2>Equipe e capacidade de entrega</h2><span class="badge ${op.overdue_tasks?'bad':''}">${op.open_tasks} atividades abertas · ${op.overdue_tasks} em atraso</span></div><div class="table-wrap"><table><thead><tr><th>Colaborador</th><th>Abertas hoje</th><th>Em andamento</th><th>Atrasadas</th><th>Concluídas no período</th></tr></thead><tbody>${op.workload.map(w=>`<tr><td><strong>${escapeHtml(w.name)}</strong></td><td>${w.open}</td><td>${w.doing}</td><td>${w.overdue}</td><td>${w.done}</td></tr>`).join('')}</tbody></table></div><p class="fine">Contagem de atividades, não horas trabalhadas. Complexidade, retrabalho e tempo gasto ainda não são medidos.</p></section><div class="finance-grid"><section class="panel"><h2>Principais clientes por recebimento</h2><div class="table-wrap"><table><thead><tr><th>Cliente</th><th>Recebido no período</th></tr></thead><tbody>${d.customers.map(c=>`<tr><td><strong>${escapeHtml(c.name)}</strong><small>${escapeHtml(c.email)}</small></td><td>${money(c.received)}</td></tr>`).join('')}</tbody></table></div>${!d.customers.length?'<p class="muted">Sem recebimentos no período.</p>':''}</section><section class="panel"><h2>Pontos de atenção para decidir</h2><ul class="bi-insights"><li><strong>${op.late.length} site(s) com prazo inicial vencido.</strong> Confira os materiais, impedimentos e a conversa do pedido antes de replanejar.</li><li><strong>${money(s.pending)} a receber</strong> em cobranças pendentes com vencimento no período; ${money(s.confirmed)} confirmados ainda separados do recebido.</li><li><strong>Custos e lucro: ainda indisponíveis.</strong> Precisamos registrar servidor, equipe, ferramentas e outras despesas para calcular margem, lucro e ponto de equilíbrio.</li></ul>${op.late.map(o=>`<button class="btn secondary" data-order="${o.id}">${escapeHtml(o.title)} · ${date(o.due_date)} ↗</button>`).join('')}</section></div><section class="panel"><h2>Qualidade e alcance dos dados</h2><p class="fine">${d.quality.orders} pedidos e ${d.quality.payments} cobranças consultados diretamente no banco para o serviço selecionado, sem o limite de 500 pedidos da lista operacional. ${d.quality.settled_without_date} recebimento(s) sem data ficam fora dos indicadores por período. Líquidos ausentes não são estimados. Taxas conhecidas não incluem despesas operacionais. Os dados refletem o último estado registrado no portal; esta consulta não força uma sincronização com Asaas.</p><p class="fine">Aquisição de leads, CAC, churn histórico, LTV e lucro exigem dados adicionais. Eles não são calculados a partir de suposições.</p></section>`;bindOrderButtons();}catch(e){box.innerHTML='<div class="empty">Não foi possível carregar os indicadores. Ajuste o período e tente novamente.</div>';const f=document.querySelector('#bi-filters');if(f)f.onsubmit=ev=>{ev.preventDefault();loadBI(new URLSearchParams(new FormData(f)).toString())};notify(e.message,true);}}

const customerFilters={query:'',product:'',status:'',sort:'received',page:1};
function clientsMarkup(){return head('Clientes, com uma visão completa.','Relacionamento, projetos e histórico de pagamentos em um só lugar.','<button class="btn secondary" id="clients-refresh">Atualizar ↻</button>')+'<div id="clients-content">Carregando clientes…</div>';}
async function loadClients(){try{const data=await api('/api/admin/clients');if(!document.querySelector('#clients-content'))return;const financial=data.financial;if(!financial&&['overdue','paid','subscription'].includes(customerFilters.status))customerFilters.status='';document.querySelector('#clients-content').innerHTML=`<section class="panel finance-filter"><form id="client-filters"><label>Cliente, empresa ou contato<input name="query" placeholder="Nome, empresa, e-mail, WhatsApp…" value="${escapeHtml(customerFilters.query)}"></label><label>Serviço<select name="product"><option value="">Todos</option>${state.config.products.map(p=>`<option value="${p.id}">${escapeHtml(p.title)}</option>`).join('')}</select></label><label>Situação<select name="status"><option value="">Todos os clientes</option><option value="open">Com projeto em andamento</option><option value="no-orders">Sem pedidos</option>${financial?'<option value="overdue">Com cobrança vencida</option><option value="paid">Com pagamentos recebidos</option><option value="subscription">Com assinatura ativa</option>':''}</select></label><label>Ordenar<select name="sort"><option value="received">${financial?'Maior total recebido':'Mais recentes'}</option><option value="recent">Cadastro mais recente</option><option value="name">Nome A–Z</option><option value="orders">Mais pedidos</option></select></label><button class="btn orange">Filtrar clientes</button><button type="button" class="btn secondary" id="clients-clear">Limpar</button></form></section><div id="clients-results"></div>`;
const form=document.querySelector('#client-filters');for(const k of ['product','status','sort'])form.elements[k].value=customerFilters[k];form.onsubmit=e=>{e.preventDefault();Object.assign(customerFilters,Object.fromEntries(new FormData(form)),{page:1});draw();};document.querySelector('#clients-clear').onclick=()=>{Object.assign(customerFilters,{query:'',product:'',status:'',sort:'received',page:1});loadClients()};document.querySelector('#clients-refresh').onclick=loadClients;
function draw(){const f=customerFilters,rows=data.clients.filter(c=>(!f.query||[c.name,c.email,...c.companies,c.contact?.phone,c.contact?.whatsapp].join(' ').toLowerCase().includes(f.query.toLowerCase()))&&(!f.product||c.products.includes(f.product))&&(!f.status||f.status==='open'&&c.open_orders>0||f.status==='no-orders'&&!c.order_count||f.status==='overdue'&&c.financial?.overdue>0||f.status==='paid'&&c.financial?.received>0||f.status==='subscription'&&c.financial?.active_subscriptions>0));rows.sort((a,b)=>f.sort==='name'?a.name.localeCompare(b.name,'pt-BR'):f.sort==='orders'?b.order_count-a.order_count:f.sort==='received'&&financial?b.financial.received-a.financial.received:b.created_at.localeCompare(a.created_at));const total=rows.reduce((n,c)=>n+(c.financial?.received||0),0),overdue=rows.reduce((n,c)=>n+(c.financial?.overdue||0),0),pages=Math.max(1,Math.ceil(rows.length/25));f.page=Math.min(f.page,pages);document.querySelector('#clients-results').innerHTML=stats(financial?[['Clientes encontrados',rows.length,'Conforme os filtros'],['Recebido acumulado',money(total),'Todo o histórico destes clientes'],['Em atraso',money(overdue),'Cobranças atualmente vencidas'],['Com projetos ativos',rows.filter(c=>c.open_orders>0).length,'Pedidos ainda não entregues']]:[['Clientes encontrados',rows.length,'Conforme os filtros'],['Com projetos ativos',rows.filter(c=>c.open_orders>0).length,'Pedidos ainda não entregues'],['Sem pedidos',rows.filter(c=>!c.order_count).length,'Contas sem projeto'],['Empresas informadas',rows.reduce((n,c)=>n+c.companies.length,0),'Nos briefings']])+`<section class="panel"><div class="panel-head"><h2>Carteira de clientes</h2><span class="fine">${rows.length} cliente(s) · página ${f.page} de ${pages}</span></div><div class="table-wrap"><table><thead><tr><th>Responsável / empresas</th><th>Contato</th><th>Projetos</th>${financial?'<th>Recebido desde o início</th><th>A receber / vencido</th>':''}<th>Cadastro</th><th></th></tr></thead><tbody>${rows.slice((f.page-1)*25,f.page*25).map(c=>`<tr><td><strong>${escapeHtml(c.name)}</strong><small>${escapeHtml(c.companies.join(' · ')||'Empresa ainda não informada')}</small></td><td>${escapeHtml(c.email)}<small>${escapeHtml(c.contact?.whatsapp||c.contact?.phone||'Telefone não informado')}</small></td><td>${c.order_count} pedido(s)<small>${c.open_orders} em andamento</small></td>${financial?`<td><strong>${money(c.financial.received)}</strong><small>${c.financial.received_count} recebimento(s)</small></td><td>${money(c.financial.pending)} pendente<small>${money(c.financial.overdue)} vencido</small></td>`:''}<td>${date(c.created_at)}</td><td><button class="btn secondary" data-customer="${c.id}">Ver ficha ↗</button></td></tr>`).join('')}</tbody></table></div>${!rows.length?'<div class="empty">Nenhum cliente encontrado para esses filtros.</div>':''}<div class="row-buttons"><button class="btn secondary" id="clients-prev" ${f.page<=1?'disabled':''}>← Anterior</button><button class="btn secondary" id="clients-next" ${f.page>=pages?'disabled':''}>Próxima →</button></div></section><p class="fine">O total recebido é acumulado desde o início do histórico registrado no portal e não é limitado pelo filtro de serviço: o filtro seleciona clientes, mantendo o valor integral de cada relacionamento. Inclui somente cobranças atualmente liquidadas (Recebido / Recebido em dinheiro); confirmados, pendentes, estornados e contestações ficam separados. Não equivale a lucro ou saldo bancário.</p>`;document.querySelectorAll('[data-customer]').forEach(b=>b.onclick=()=>openCustomer(b.dataset.customer));document.querySelector('#clients-prev').onclick=()=>{f.page--;draw()};document.querySelector('#clients-next').onclick=()=>{f.page++;draw()};}draw();}catch(e){notify(e.message,true);}}
async function openCustomer(id){try{const data=await api('/api/admin/clients/'+id),c=data.clients[0],s=c.financial;let html=`<span class="eyebrow">Ficha do cliente</span><h2>${escapeHtml(c.name)}</h2><p>${escapeHtml(c.email)}</p><p class="fine">Cadastro: ${date(c.created_at)} · Última atualização de pedido ou material: ${date(c.last_activity)}</p>`;if(s)html+=stats([['Recebido desde o início',money(s.received),`${s.received_count} recebimento(s) no histórico`],['Líquido informado',money(s.net),s.net_missing?`${s.net_missing} valor(es) líquido(s) ausente(s)`:'Após taxas informadas'],['Pendente',money(s.pending),'Aguardando pagamento'],['Vencido',money(s.overdue),'Em atraso']])+`<div class="banner">Primeiro recebimento com data registrada: ${date(s.first_payment)} · Último: ${date(s.last_payment)}.<br>Confirmado, ainda separado do recebido: ${money(s.confirmed)} · Estornado integralmente: ${money(s.refunded)} · Assinaturas ativas: ${s.active_subscriptions}.${s.review_count?`<br>${s.review_count} cobrança(s) em estorno parcial, solicitação de estorno ou contestação exigem conferência financeira.`:''}${s.undated_payments?`<br>${s.undated_payments} recebimento(s) sem data informada; incluídos no acumulado.`:''}</div>`;
html+=`<h3>Empresas e contatos enviados nos pedidos</h3>${c.contacts.length?c.contacts.map(v=>`<details class="message"><summary>${escapeHtml(v.company_name||'Empresa não informada')}</summary><p>${escapeHtml(v.title)}</p><dl class="client-contact">${[['E-mail',v.email],['WhatsApp',v.whatsapp],['Telefone',v.phone],['Endereço',v.address],['Domínio',v.domain],['Site',v.contact_site||v.current_site]].map(([k,v])=>`<div><dt>${k}</dt><dd>${escapeHtml(v||'Não informado')}</dd></div>`).join('')}</dl></details>`).join(''):'<p class="muted">Nenhum contato empresarial enviado nos briefings.</p>'}<h3>Todos os pedidos · ${c.orders.length}</h3><div class="table-wrap"><table><thead><tr><th>Pedido</th><th>Situação</th><th>Criação</th><th>Última atualização</th><th></th></tr></thead><tbody>${c.orders.map(o=>`<tr><td>${escapeHtml(o.title)}</td><td>${badge(o.phase)}</td><td>${date(o.created_at)}</td><td>${date(o.updated_at)}</td><td><button class="btn secondary" data-order="${o.id}">Ver pedido ↗</button></td></tr>`).join('')}</tbody></table></div>`;
if(s)html+=`<h3>Histórico completo de cobranças · ${c.payments.length}</h3><div class="table-wrap"><table><thead><tr><th>Pedido</th><th>Tipo</th><th>Bruto</th><th>Líquido</th><th>Vencimento</th><th>Recebimento</th><th>Situação</th></tr></thead><tbody>${c.payments.map(p=>`<tr><td>${escapeHtml(c.orders.find(o=>o.id===p.order_id)?.title||p.order_id)}</td><td>${p.kind==='maintenance'?'Assinatura':'Projeto / implantação'}</td><td>${money(p.value_cents)}</td><td>${p.net_cents===null?'—':money(p.net_cents)}</td><td>${date(p.due_date)}</td><td>${date(p.paid_at)}</td><td>${badge(p.status)}</td></tr>`).join('')}</tbody></table></div><p class="fine">Acumulado de valores brutos atualmente liquidados, com estornos separados. Os registros são do portal e refletem a última sincronização disponível.</p>`;showDialog(html);bindOrderButtons();}catch(e){notify(e.message,true);}}

const opsFilters={query:'',stage:'',product:'',signal:'',assignee:'',payment:'',from:'',to:'',sort:'attention',page:1};
const opsStages={payment:'Aguardando pagamento',preparation:'Preparação / materiais',production:'Produção',changes:'Ajustes',review:'Revisão do cliente',approved:'Aprovado para publicação',published:'Publicado',solicitado:'Solicitado',planejamento:'Planejamento',desenvolvimento:'Desenvolvimento',revisao:'Em revisão',entregue:'Entregue'};
function ordersOpsMarkup(){return head('Pedidos sob controle.','Jornada, pendências, responsáveis e reclamações em uma única visão.','<button class="btn secondary" id="ops-refresh">Atualizar ↻</button>')+'<div id="ops-content">Carregando pedidos…</div>';}
async function loadOrdersOps(){try{const d=await api('/api/admin/orders');if(!document.querySelector('#ops-content'))return;const assignees=[...new Map(d.orders.flatMap(o=>o.assignees).map(a=>[a.id,a])).values()];document.querySelector('#ops-content').innerHTML=`<section class="panel finance-filter"><form id="ops-filters"><label>Cliente ou pedido<input name="query" placeholder="Nome, e-mail, pedido…" value="${escapeHtml(opsFilters.query)}"></label><label>Jornada<select name="stage"><option value="">Todas as etapas</option>${Object.entries(opsStages).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></label><label>Serviço<select name="product"><option value="">Todos</option>${state.config.products.map(p=>`<option value="${p.id}">${escapeHtml(p.title)}</option>`).join('')}</select></label><label>Atenção<select name="signal"><option value="">Todos</option><option value="complaint">Reclamação em aberto</option><option value="high">Reclamação prioritária</option><option value="late">Prazo inicial vencido</option><option value="task-late">Atividade atrasada</option><option value="blocked">Atividade bloqueada</option><option value="unanswered">Cliente aguardando resposta</option><option value="materials">Materiais pendentes / complemento</option><option value="materials-review">Materiais enviados para análise</option><option value="unassigned">Atividade sem responsável</option></select></label><label>Responsável por atividade aberta<select name="assignee"><option value="">Todos</option>${assignees.map(a=>`<option value="${a.id}">${escapeHtml(a.name)}</option>`).join('')}</select></label>${d.financial?`<label>Pagamento<select name="payment"><option value="">Todos</option>${['NOT_CREATED','PENDING','CONFIRMED','RECEIVED','RECEIVED_IN_CASH','OVERDUE','REFUNDED'].map(s=>`<option value="${s}">${statusLabels[s]}</option>`).join('')}<option value="any-overdue">Qualquer cobrança vencida</option></select></label>`:''}<label>Criado de<input name="from" type="date" value="${opsFilters.from}"></label><label>Criado até<input name="to" type="date" value="${opsFilters.to}"></label><label>Ordenar<select name="sort"><option value="attention">Mais atenção primeiro</option><option value="recent">Mais recentes</option><option value="old">Mais antigos</option><option value="due">Prazo inicial mais próximo</option></select></label><button class="btn orange">Filtrar pedidos</button><button class="btn secondary" id="ops-clear" type="button">Limpar</button></form></section><div id="ops-results"></div>`;
const form=document.querySelector('#ops-filters');for(const k of ['stage','product','signal','assignee','payment','sort'])if(form.elements[k])form.elements[k].value=opsFilters[k];if(!d.financial)opsFilters.payment='';form.onsubmit=e=>{e.preventDefault();const values=Object.fromEntries(new FormData(form));if(values.from&&values.to&&values.from>values.to)return notify('Revise o período de criação.',true);Object.assign(opsFilters,values,{page:1});draw()};document.querySelector('#ops-clear').onclick=()=>{Object.assign(opsFilters,{query:'',stage:'',product:'',signal:'',assignee:'',payment:'',from:'',to:'',sort:'attention',page:1});loadOrdersOps()};document.querySelector('#ops-refresh').onclick=loadOrdersOps;
function draw(){const f=opsFilters,signals={'materials-review':o=>o.briefing_status==='submitted',complaint:o=>o.open_complaints>0,high:o=>o.high_complaints>0,late:o=>o.late,'task-late':o=>o.overdue_tasks>0,blocked:o=>o.blocked,unanswered:o=>o.unanswered,materials:o=>o.stage==='preparation'&&['not_started','draft','revision_requested'].includes(o.briefing_status),unassigned:o=>o.tasks.some(t=>!t.assignee_id)},score=o=>o.high_complaints*100+o.open_complaints*50+(o.late?30:0)+(o.blocked?20:0)+(o.unanswered?10:0)+o.overdue_tasks,rows=d.orders.filter(o=>(!f.query||[o.title,o.client_name,o.client_email,o.id,...o.complaints.map(c=>c.subject)].join(' ').toLowerCase().includes(f.query.toLowerCase()))&&(!f.stage||o.stage===f.stage)&&(!f.product||o.product_id===f.product)&&(!f.signal||signals[f.signal]?.(o))&&(!f.assignee||o.assignees.some(a=>a.id===f.assignee))&&(!f.payment||f.payment==='any-overdue'?(!f.payment||o.overdue_payment):o.payment_status===f.payment)&&(!f.from||o.created_at.slice(0,10)>=f.from)&&(!f.to||o.created_at.slice(0,10)<=f.to));rows.sort((a,b)=>f.sort==='attention'?score(b)-score(a)||b.created_at.localeCompare(a.created_at):f.sort==='due'?(a.due_date||'9999').localeCompare(b.due_date||'9999'):f.sort==='old'?a.created_at.localeCompare(b.created_at):b.created_at.localeCompare(a.created_at));const pages=Math.max(1,Math.ceil(rows.length/25));f.page=Math.min(f.page,pages);const next=o=>o.open_complaints?'Tratar reclamação':o.blocked?'Resolver impedimento':o.unanswered?'Responder ao cliente':o.stage==='payment'?'Acompanhar pagamento':o.stage==='preparation'?(o.briefing_status==='submitted'?'Conferir materiais':o.briefing_status==='approved'?'Iniciar produção':'Aguardar materiais do cliente'):o.stage==='review'?'Aguardar decisão do cliente':o.stage==='approved'?'Publicar versão aprovada':o.stage==='published'?'Acompanhar suporte':o.tasks[0]?.title||'Atualizar andamento';document.querySelector('#ops-results').innerHTML=stats([['Pedidos encontrados',rows.length,'Conforme os filtros'],['Reclamações abertas',rows.reduce((n,o)=>n+o.open_complaints,0),'Ocorrências não resolvidas'],['Prazo inicial vencido',rows.filter(o=>o.late).length,'Conferir acordos e impedimentos'],['Aguardando resposta',rows.filter(o=>o.unanswered).length,'Última mensagem foi do cliente']])+`<div class="ops-journey">${Object.entries(opsStages).filter(([k])=>d.orders.some(o=>o.stage===k)).map(([k,v])=>`<button data-ops-stage="${k}" class="${f.stage===k?'active':''}"><strong>${d.orders.filter(o=>o.stage===k).length}</strong>${v}</button>`).join('')}</div><section class="panel"><div class="panel-head"><h2>Acompanhamento dos pedidos</h2><span class="fine">${rows.length} registro(s) · página ${f.page} de ${pages}</span></div><div class="table-wrap"><table class="ops-table"><thead><tr><th>Pedido / cliente</th><th>Jornada / evolução</th><th>Responsáveis / próxima ação</th><th>Prazo / alertas</th>${d.financial?'<th>Pagamento</th>':''}<th></th></tr></thead><tbody>${rows.slice((f.page-1)*25,f.page*25).map(o=>`<tr><td><strong>${escapeHtml(o.title)}</strong><small>${escapeHtml(o.client_name)} · ${escapeHtml(o.client_email)}</small><small>#${o.id.slice(0,8)} · Criado ${date(o.created_at)}</small></td><td><span class="badge">${opsStages[o.stage]||escapeHtml(o.stage)}</span>${o.product_id==='site'&&['production','changes','review','approved','published'].includes(o.stage)?`<progress max="100" value="${o.progress}" aria-label="Evolução de ${escapeHtml(o.title)}">${o.progress}%</progress><small>${o.progress}% dos marcos registrados</small>`:''}<small>Atualizado ${date(o.updated_at)}</small></td><td><strong>${escapeHtml(o.assignees.map(a=>a.name).join(', ')||'Sem atividade atribuída')}</strong><small>Próxima ação sugerida: ${escapeHtml(next(o))}</small><small>${o.tasks.length} atividade(s) aberta(s)</small></td><td>${o.due_date?'Previsão inicial: '+date(o.due_date):'Prazo não iniciado'}<div class="ops-alerts">${o.late?'<span class="badge bad">Prazo inicial vencido</span>':''}${o.open_complaints?`<span class="badge bad">${o.open_complaints} reclamação(ões) aberta(s)</span>`:''}${o.high_complaints?'<span class="badge bad">Prioridade alta</span>':''}${o.unanswered?'<span class="badge warn">Cliente aguarda resposta</span>':''}${o.blocked?'<span class="badge bad">Atividade bloqueada</span>':''}${o.overdue_tasks?`<span class="badge warn">${o.overdue_tasks} atividade(s) atrasada(s)</span>`:''}${!o.late&&!o.open_complaints&&!o.unanswered&&!o.blocked&&!o.overdue_tasks?'<small>Sem alertas registrados</small>':''}</div></td>${d.financial?`<td>${badge(o.payment_status)}${o.overdue_payment?'<small>Cobrança vencida no histórico</small>':''}</td>`:''}<td><div class="ops-buttons"><button class="btn secondary" data-order="${o.id}">Ver pedido ↗</button><button class="btn secondary" data-ops-complaint="${o.id}">Reclamações (${o.complaints.length})</button></div></td></tr>`).join('')}</tbody></table></div>${!rows.length?'<div class="empty">Nenhum pedido corresponde aos filtros.</div>':''}<div class="row-buttons"><button class="btn secondary" id="ops-prev" ${f.page<=1?'disabled':''}>← Anterior</button><button class="btn secondary" id="ops-next" ${f.page>=pages?'disabled':''}>Próxima →</button></div></section><p class="fine">Jornada e contagens superiores consideram todos os pedidos acessíveis; indicadores e tabela consideram os filtros. Responsáveis são os colaboradores de atividades abertas. Prazo inicial vencido é um alerta para conferência: ajustes, feriados e acordos podem alterar o prazo efetivo. Reclamações são registros explícitos, sem classificação automática de mensagens. Fonte: banco completo do portal.</p>`;bindOrderButtons();document.querySelectorAll('[data-ops-complaint]').forEach(b=>b.onclick=async()=>{await openOrder(b.dataset.opsComplaint);document.querySelector('#order-complaints')?.scrollIntoView({block:'start'})});document.querySelectorAll('[data-ops-stage]').forEach(b=>b.onclick=()=>{f.stage=b.dataset.opsStage;f.page=1;form.elements.stage.value=f.stage;draw()});document.querySelector('#ops-prev').onclick=()=>{f.page--;draw()};document.querySelector('#ops-next').onclick=()=>{f.page++;draw()};}draw();}catch(e){notify(e.message,true);}}
function complaintsMarkup(o){const manager=state.user.role==='admin'&&(!state.user.staff_profile||state.user.staff_profile==='atendimento'),canCreate=manager||state.user.role==='client',labels={open:'Aberta',handling:'Em atendimento',resolved:'Resolvida'};return `<section id="order-complaints" class="briefing-panel"><h3>Reclamações e acompanhamento</h3><p class="fine">Registre o problema e acompanhe a resposta da Imagine. A conclusão de uma tarefa não resolve automaticamente uma reclamação; a resolução precisa ser registrada aqui.</p>${(o.complaints||[]).map(c=>`<article class="panel"><div class="panel-head"><h3>${escapeHtml(c.subject)}</h3><span class="badge ${c.status==='resolved'?'good':'bad'}">${labels[c.status]} · ${c.priority==='high'?'Alta prioridade':'Normal'}</span></div><p class="fine">${escapeHtml(c.author)} · ${date(c.created_at)}</p><p class="scope-preview">${escapeHtml(c.body)}</p>${c.events.map(h=>`<article class="message"><header>${escapeHtml(h.name)} · ${date(h.created_at)} · ${labels[h.status]}</header><p>${escapeHtml(h.note)}</p></article>`).join('')}${manager?`<form class="complaint-update" data-id="${c.id}" data-version="${c.version}"><label class="field"><span>Situação da reclamação</span><select name="status">${Object.entries(labels).map(([k,v])=>`<option value="${k}" ${k===c.status?'selected':''}>${v}</option>`).join('')}</select></label><label class="field"><span>Resposta ou encaminhamento ao cliente</span><textarea name="note" minlength="5" maxlength="4000" required></textarea></label><button class="btn secondary">Registrar atendimento</button></form>`:''}</article>`).join('')||'<p class="muted">Nenhuma reclamação registrada neste pedido.</p>'}${canCreate?'<details><summary>Registrar nova reclamação</summary><form id="complaint-create"><label class="field"><span>Assunto</span><input name="subject" required minlength="5" maxlength="160"></label><label class="field"><span>Prioridade</span><select name="priority"><option value="normal">Normal</option><option value="high">Alta</option></select></label><label class="field"><span>Descreva o problema</span><textarea name="body" required minlength="10" maxlength="4000"></textarea></label><button class="btn orange">Registrar reclamação</button></form></details>':''}</section>`;}
function bindComplaints(o,refresh){document.querySelector('#complaint-create')?.addEventListener('submit',e=>{e.preventDefault();task(e.submitter,async()=>{await post('/api/orders/'+o.id+'/complaints',{action:'create',...Object.fromEntries(new FormData(e.target))});await refresh();notify('Reclamação registrada e encaminhada para acompanhamento.');})});document.querySelectorAll('.complaint-update').forEach(f=>f.onsubmit=e=>{e.preventDefault();task(e.submitter,async()=>{await post('/api/orders/'+o.id+'/complaints',{id:f.dataset.id,version:Number(f.dataset.version),...Object.fromEntries(new FormData(f))});await refresh();notify('Atendimento registrado no histórico.');})});}

const workFilters={query:'',status:'open',priority:'',deadline:'',assignee:'',kind:'',sort:'recommended',selected:null,archive:'active'};
const workStatus={pending:'A fazer',doing:'Em execução',blocked:'Bloqueada',done:'Concluída',canceled:'Cancelada'},workPriority={critical:'Urgente',high:'Alta',normal:'Normal',low:'Baixa'};
function workDeadline(t,today){if(t.archived_at)return {key:'archived',label:'Arquivada',days:0};if(t.status==='canceled')return {key:'canceled',label:'Cancelada',days:0};if(t.status==='done')return {key:'done',label:'Concluída',days:0};const days=Math.round((new Date(t.due_date+'T12:00:00Z')-new Date(today+'T12:00:00Z'))/86400000);return {key:days<0?'late':days===0?'today':'ontime',label:days<0?`Atrasada há ${-days} dia(s)`:days===0?'Vence hoje':days===1?'Vence amanhã':`No prazo · ${date(t.due_date)}`,days};}
async function loadWork(){try{const d=await api('/api/team/tasks'),box=document.querySelector('#team-content');if(!box)return;const manager=!state.user.staff_profile,today=d.today,open=d.tasks.filter(t=>!['done','canceled'].includes(t.status)&&!t.archived_at);box.innerHTML=`<section class="work-intro"><div><span class="eyebrow">Seu ambiente de trabalho</span><h2>Clareza para fazer. Foco para entregar.</h2><p>Escolha uma atividade, confira as instruções e registre o próximo passo.</p></div><span class="badge">${manager?'Visão da equipe':'Suas atividades atribuídas'}</span><button class="btn orange" id="work-new-task">Nova atividade +</button></section><div class="work-summary">${[['late','Atrasadas',open.filter(t=>workDeadline(t,today).key==='late').length,'Precisam de atenção'],['today','Vencem hoje',open.filter(t=>t.due_date===today).length,'Organize sua entrega'],['doing','Em execução',open.filter(t=>t.status==='doing').length,'Trabalho iniciado'],['blocked','Bloqueadas',open.filter(t=>t.status==='blocked').length,'Resolva o impedimento']].map(([k,label,n,sub])=>`<button data-work-shortcut="${k}" class="${k==='late'?'work-late':''}"><span>${label}</span><strong>${n}</strong><small>${sub}</small></button>`).join('')}</div><section class="panel finance-filter"><form id="work-filters"><label>Buscar atividade ou cliente<input name="query" value="${escapeHtml(workFilters.query)}" placeholder="O que você precisa encontrar?"></label><label>Situação<select name="status"><option value="open">Todas abertas</option><option value="pending">A fazer</option><option value="doing">Em execução</option><option value="blocked">Bloqueadas</option><option value="done">Concluídas</option><option value="canceled">Canceladas</option><option value="all">Todas as situações</option></select></label><label>Arquivo<select name="archive"><option value="active">Não arquivadas</option><option value="archived">Arquivadas</option><option value="all">Com e sem arquivo</option></select></label><label>Prioridade<select name="priority"><option value="">Todas</option>${Object.entries(workPriority).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></label><label>Prazo<select name="deadline"><option value="">Todos</option><option value="late">Atrasadas</option><option value="today">Vencem hoje</option><option value="ontime">No prazo (futuro)</option></select></label>${manager?`<label>Responsável<select name="assignee"><option value="">Toda a equipe</option><option value="mine">Minhas atividades</option><option value="none">Sem responsável</option>${d.members.map(m=>`<option value="${m.id}">${escapeHtml(m.name)}${m.active?'':' · Desativado'}</option>`).join('')}</select></label>`:''}<label>Tipo<select name="kind"><option value="">Todos</option>${Object.entries(d.kinds).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></label><label>Ordenar<select name="sort"><option value="recommended">Prioridade, atraso e prazo</option><option value="due">Prazo mais próximo</option><option value="recent">Mais recentes</option></select></label><button class="btn orange">Aplicar</button><button class="btn secondary" id="work-clear" type="button">Limpar</button></form></section><div class="work-legend"><span><i class="dot late"></i>Atrasada</span><span><i class="dot today"></i>Vence hoje</span><span><i class="dot ontime"></i>No prazo</span><span class="fine">Prazo da atividade em dias corridos · ${date(today)}</span></div><div class="work-layout"><section class="work-queue"><div class="panel-head"><h2>Sua fila de trabalho</h2><span id="work-count" class="fine"></span></div><div id="work-list"></div></section><section id="work-detail" class="panel work-detail" aria-live="polite"></section></div><p class="fine">Prioridades e prazos podem ser definidos pela administração. A ordem sugerida considera prioridade, atraso e vencimento; não altera os prazos. A etapa concluída no pedido pode encerrar a atividade automaticamente. Checklist registra a conferência do colaborador. Automação a cada 30 segundos no servidor; use Atualizar para consultar a posição atual. Até 1.000 atividades carregadas, priorizando abertas.</p>`;
document.querySelector('#work-new-task').onclick=()=>newManualTask(d);const form=document.querySelector('#work-filters');for(const k of ['status','priority','deadline','assignee','kind','sort','archive'])if(form.elements[k])form.elements[k].value=workFilters[k]||(k==='archive'?'active':'');form.onsubmit=e=>{e.preventDefault();const values=Object.fromEntries(new FormData(form));if(values.archive==='archived'&&values.status==='open'){values.status='all';form.elements.status.value='all';}Object.assign(workFilters,values);draw()};document.querySelector('#work-clear').onclick=()=>{Object.assign(workFilters,{archive:'active',query:'',status:'open',priority:'',deadline:'',assignee:'',kind:'',sort:'recommended'});loadWork()};document.querySelector('#team-refresh').onclick=loadWork;document.querySelectorAll('[data-work-shortcut]').forEach(b=>b.onclick=()=>{const k=b.dataset.workShortcut;workFilters.deadline=['late','today'].includes(k)?k:'';workFilters.status=['doing','blocked'].includes(k)?k:'open';form.elements.deadline.value=workFilters.deadline;form.elements.status.value=workFilters.status;draw()});
function draw(){const f=workFilters,rank={critical:0,high:1,normal:2,low:3},rows=d.tasks.filter(t=>(f.archive==='all'||f.archive==='archived'?f.archive==='all'||!!t.archived_at:!t.archived_at)&&(f.status==='all'||f.status==='open'&&!['done','canceled'].includes(t.status)||t.status===f.status)&&(!f.query||[t.title,t.context?.action,t.context?.request?.body,t.order_title,t.client_name,t.instructions].join(' ').toLowerCase().includes(f.query.toLowerCase()))&&(!f.priority||t.priority===f.priority)&&(!f.deadline||workDeadline(t,today).key===f.deadline)&&(!f.kind||t.kind===f.kind)&&(!f.assignee||f.assignee==='mine'&&t.assignee_id===state.user.id||f.assignee==='none'&&(!t.assignee_id||d.members.find(m=>m.id===t.assignee_id)?.active===0)||t.assignee_id===f.assignee));rows.sort((a,b)=>f.sort==='recent'?b.created_at.localeCompare(a.created_at):f.sort==='due'?a.due_date.localeCompare(b.due_date):(rank[a.priority]-rank[b.priority])||((workDeadline(a,today).key==='late'?0:1)-(workDeadline(b,today).key==='late'?0:1))||a.due_date.localeCompare(b.due_date));document.querySelector('#work-count').textContent=rows.length+' atividade(s)';if(!rows.some(t=>t.id===f.selected))f.selected=rows[0]?.id||null;document.querySelector('#work-list').innerHTML=rows.map(t=>{const due=workDeadline(t,today);return `<button class="work-item ${f.selected===t.id?'selected':''}" data-work-id="${t.id}"><span class="work-item-top"><span class="work-priority ${t.priority}">${workPriority[t.priority]}</span><span class="work-date ${due.key}">${due.label}</span></span><strong>${escapeHtml(t.context?.action||t.title)}</strong>${t.context?.request?`<span class="work-excerpt">“${escapeHtml(t.context.request.body.slice(0,160))}${t.context.request.body.length>160?'…':''}”</span>`:''}<span class="work-order">${escapeHtml(t.order_title)}</span><span class="work-item-bottom"><span>${escapeHtml(t.assignee||'Sem responsável')}</span><span>${workStatus[t.status]} →</span></span></button>`}).join('')||'<div class="panel empty">Nenhuma atividade para estes filtros. Ajuste a seleção para continuar.</div>';document.querySelectorAll('[data-work-id]').forEach(b=>b.onclick=()=>{f.selected=b.dataset.workId;draw()});detail(rows.find(t=>t.id===f.selected));}
function detail(t){const panel=document.querySelector('#work-detail');if(!t){panel.innerHTML='<div class="empty">Selecione uma atividade na fila para ver o que fazer.</div>';return;}const due=workDeadline(t,today),done=t.checklist.filter(c=>c.done).length;panel.innerHTML=`<div class="work-detail-top"><span class="eyebrow">${escapeHtml(d.kinds[t.kind]||t.kind)}</span><span class="work-date ${due.key}">${due.label}</span></div><div class="work-title-row"><h2>${escapeHtml(t.context?.action||t.title)}</h2><span class="work-help"><button class="work-help-toggle" type="button" aria-label="Orientações de execução" aria-expanded="false">!</button><span class="work-help-popover" role="tooltip"><strong>${escapeHtml(t.goal)}</strong><p>${escapeHtml(t.instructions)}</p></span></span></div><p class="muted">${escapeHtml(t.order_title)} · ${escapeHtml(t.client_name)}</p>${taskManagementButtons(t)}${workClientContext(t)}<div class="work-context"><span><small>Responsável</small><strong>${escapeHtml(t.assignee||'Sem responsável')}</strong></span><span><small>Situação</small><strong>${workStatus[t.status]}</strong></span><span><small>Prioridade</small><strong>${workPriority[t.priority]}</strong></span><span><small>Prazo</small><strong>${date(t.due_date)}</strong></span></div><form id="work-action"><details class="work-checklist-fold"><summary>Checklist de conferência · ${done}/${t.checklist.length}</summary><div class="panel-head"><h3>Checklist de execução</h3><span class="fine">${done} de ${t.checklist.length} conferidos</span></div><div class="work-checklist">${t.checklist.map(c=>`<label><input type="checkbox" name="check-${c.id}" ${c.done?'checked':''} ${t.status==='done'||t.status==='canceled'||t.archived_at?'disabled':''}><span>${escapeHtml(c.label)}</span></label>`).join('')}</div><p class="fine">Salve o acompanhamento para registrar os itens conferidos. A conclusão manual exige todos os itens.</p></details>${t.note?`<div class="banner"><strong>Último encaminhamento</strong><br>${escapeHtml(t.note)}</div>`:''}<label class="field"><span>Seu andamento ou impedimento</span><textarea name="note" maxlength="4000" placeholder="O que foi feito? O que falta? Se estiver bloqueada, informe o impedimento e o próximo passo."></textarea></label>${manager&&!t.archived_at&&t.status!=='canceled'?`<details class="work-management"><summary>Gerenciar prioridade, prazo e instruções</summary><div class="team-form"><label class="field"><span>Prioridade</span><select name="priority">${Object.entries(workPriority).map(([k,v])=>`<option value="${k}" ${t.priority===k?'selected':''}>${v}</option>`).join('')}</select></label><label class="field"><span>Prazo da atividade</span><input type="date" name="due_date" value="${t.due_date}" required></label><label class="field"><span>Responsável</span><select name="assignee_id"><option value="">Sem responsável</option>${!d.members.some(m=>m.id===state.user.id)?`<option value="${state.user.id}" ${state.user.id===t.assignee_id?'selected':''}>Eu · ${escapeHtml(state.user.name)}</option>`:''}${d.members.filter(m=>m.active||m.id===t.assignee_id).map(m=>`<option value="${m.id}" ${m.id===t.assignee_id?'selected':''}>${escapeHtml(m.name)}${m.active?'':' · Desativado'}</option>`).join('')}</select></label></div><label class="field"><span>Resultado esperado</span><input name="goal" value="${escapeHtml(t.goal)}" maxlength="500"></label><label class="field"><span>Instruções de execução</span><textarea name="instructions" minlength="10" maxlength="6000">${escapeHtml(t.instructions)}</textarea></label><p class="fine">Registre o motivo da alteração no campo de andamento. Alterar prazo desta atividade não muda o prazo contratado do pedido.</p></details>`:''}<div class="work-actions"><button class="btn secondary" type="button" id="work-order">Abrir pedido ↗</button>${!['done','canceled'].includes(t.status)&&!t.archived_at?`${t.status!=='doing'?'<button class="btn orange" name="action" value="start">Iniciar agora</button>':''}<button class="btn secondary" name="action" value="save">Salvar acompanhamento</button><button class="btn secondary" name="action" value="block">Registrar bloqueio</button><button class="btn orange" name="action" value="done">Concluir atividade ✓</button>`:`<span class="badge">${t.archived_at?'Arquivada':workStatus[t.status]}</span>`}</div></form><details class="work-history"><summary>Histórico de atualizações (${t.updates.length})</summary>${t.updates.map(h=>`<article class="message"><header>${escapeHtml(h.name)} · ${date(h.created_at)} · ${workStatus[h.status]}</header><p>${escapeHtml(h.note)}</p></article>`).join('')||'<p class="fine">Sem atualizações manuais. O status também acompanha as etapas concluídas no pedido.</p>'}</details>`;
document.querySelectorAll('[data-task-manage]').forEach(b=>b.onclick=()=>manageTaskDialog(t,d,b.dataset.taskManage));document.querySelector('.work-help-toggle').onclick=e=>{const b=e.currentTarget;b.setAttribute('aria-expanded',b.getAttribute('aria-expanded')==='true'?'false':'true')};if(t.order_id)document.querySelector('#work-order').onclick=()=>openOrder(t.order_id);else document.querySelector('#work-order').remove();document.querySelector('#work-action').onsubmit=e=>{e.preventDefault();const action=e.submitter.value,values=Object.fromEntries(new FormData(e.target)),checklist=t.checklist.map(c=>({id:c.id,done:e.target.elements['check-'+c.id].checked}));if(['block','done'].includes(action)&&!values.note.trim())return notify('Descreva o impedimento ou a conclusão antes de registrar.',true);const changed=manager&&['priority','due_date','assignee_id','goal','instructions'].some(k=>values[k]!==String(t[k]??''));if(changed&&!values.note.trim())return notify('Registre o motivo da alteração no campo de andamento.',true);const status=action==='start'?'doing':action==='block'?'blocked':action==='done'?'done':t.status;task(e.submitter,async()=>{await post('/api/team/tasks',{id:t.id,version:t.version,status,checklist,note:values.note.trim()||(action==='start'?'Atividade iniciada pelo colaborador.':'Checklist de execução conferido.'),...(manager?Object.fromEntries(['priority','due_date','assignee_id','goal','instructions'].map(k=>[k,values[k]])):{})});await loadWork();notify('Atividade atualizada.');})};}draw();}catch(e){notify(e.message,true);}}

function overviewMarkup(){return head('O dia da Imagine, em uma visão.','O que precisa de atenção, o que entrou e o que pode avançar.','<button class="btn secondary" id="overview-refresh">Atualizar agora ↻</button>')+'<div id="overview-content" aria-live="polite">Preparando seu resumo…</div>';}
async function loadOverview(){clearTimeout(loadOverview.timer);try{const d=await api('/api/admin/overview');if(state.tab!=='overview'||!document.querySelector('#overview-content'))return;const c=d.counts,f=d.finance,max=Math.max(1,...d.days.map(x=>x.value));const chart=d.days.map((x,i)=>{const h=130*x.value/max;return `<g><title>${date(x.day)}: ${money(x.value)}, ${x.count} recebimento(s)</title><rect x="${20+i*65}" y="${150-h}" width="34" height="${h}" rx="4" fill="${x.day===d.today?'#171b19':'#f9941d'}"/><text x="${37+i*65}" y="172" text-anchor="middle" font-size="10" fill="#777">${x.day.slice(8)}/${x.day.slice(5,7)}</text></g>`}).join('');
document.querySelector('#overview-content').innerHTML=`<div class="overview-date"><span class="badge">Hoje · ${date(d.today)} · Horário de Brasília</span><span class="fine">Atualizado ${new Date(d.generated_at).toLocaleTimeString('pt-BR',{timeZone:'America/Sao_Paulo',hour:'2-digit',minute:'2-digit'})} · Atualização automática a cada minuto</span></div><section class="overview-attention"><div class="panel-head"><div><span class="eyebrow">Primeiro, o que precisa de você</span><h2>Prioridades da operação</h2></div></div><div class="overview-signals">${[['late','Atividades atrasadas',c.late_tasks,'Conferir responsáveis e impedimentos'],['messages','Mensagens sem resposta',c.unanswered,'Pedidos cuja última mensagem é do cliente'],['complaints','Reclamações abertas',c.complaints,'Acompanhar atendimento e resolução'],['blocked','Atividades bloqueadas',c.blocked,'Remover obstáculos da equipe']].map(([k,label,n,sub])=>`<button class="${n?'needs-attention':''}" data-overview="${k}"><span>${label}</span><strong>${n}</strong><small>${sub}</small><b>Ver fila →</b></button>`).join('')}</div></section><div class="stats"><article class="stat finance-primary"><span class="stat-label">Recebido hoje · bruto</span><strong>${money(f.received)}</strong><small>${f.count} pagamento(s) liquidado(s)</small></article><article class="stat"><span class="stat-label">Líquido informado hoje</span><strong>${money(f.net)}</strong><small>${f.net_missing?`${f.net_missing} recebimento(s) sem líquido informado`:'Após taxas informadas pelo Asaas'}</small></article><article class="stat"><span class="stat-label">A receber com vencimento hoje</span><strong>${money(f.due_today)}</strong><small>Pendentes, vencidos e confirmados ainda não liquidados</small></article><article class="stat finance-danger"><span class="stat-label">Total vencido · carteira atual</span><strong>${money(f.overdue)}</strong><small>Todos os vencimentos em atraso</small></article></div><div class="overview-pulse">${[['today','Vencem hoje',c.today_tasks,'atividades'],['unassigned','Sem responsável ativo',c.unassigned,'atividades'],['ready','Prontos para publicar',c.ready,'pedidos aprovados'],['materials','Materiais para conferir',c.materials,'briefings enviados'],['review','Na revisão do cliente',c.review,'prévias'],['new','Novos pedidos hoje',c.new_orders,'pedidos']].map(([k,label,n,sub])=>`<button data-overview="${k}"><strong>${n}</strong><span>${label}</span><small>${sub} →</small></button>`).join('')}</div><div class="finance-grid"><section class="panel"><div class="panel-head"><h2>Recebimentos · últimos 7 dias</h2><button class="btn secondary" data-overview="finance">Financeiro ↗</button></div><svg class="overview-chart" viewBox="0 0 475 185" role="img" aria-label="Recebimentos brutos diários nos últimos sete dias"><line x1="5" y1="150" x2="470" y2="150" stroke="#ddd"/>${chart}</svg><details><summary>Conferir valores por dia</summary><table><thead><tr><th>Dia</th><th>Recebido bruto</th><th>Pagamentos</th></tr></thead><tbody>${d.days.map(x=>`<tr><td>${date(x.day)}</td><td>${money(x.value)}</td><td>${x.count}</td></tr>`).join('')}</tbody></table></details><p class="fine">Somente recebimentos liquidados pela data de pagamento. ${money(f.confirmed_today)} em cobranças confirmadas com vencimento hoje ainda estão separados do recebido.</p></section><section class="panel"><div class="panel-head"><h2>Próximas decisões</h2><button class="btn secondary" data-overview="bi">Abrir BI ↗</button></div>${d.handoffs.length?d.handoffs.map(o=>`<button class="overview-handoff" data-order="${o.id}"><span><strong>${o.label}</strong><small>${escapeHtml(o.title)}</small></span><b>↗</b></button>`).join(''):'<div class="empty">Nenhum material, revisão ou publicação pendente registrado.</div>'}<p class="fine">${c.due_sites} site(s) com previsão inicial de produção para hoje. Confira os acordos registrados antes de cobrar a entrega.</p></section></div><section class="panel"><div class="panel-head"><h2>Fila de atenção da empresa</h2><span class="fine">Até 12 ocorrências prioritárias · um pedido pode aparecer mais de uma vez</span></div>${d.triage.length?d.triage.map(t=>`<button class="overview-triage" ${t.task_id?`data-overview-task="${t.task_id}"`:`data-order="${t.order_id}"`}><span class="overview-type ${t.kind}">${t.kind==='complaint'?'Reclamação':t.kind==='task'?'Atraso':'Mensagem'}</span><span><strong>${escapeHtml(t.title)}</strong><small>${escapeHtml(t.context)}</small><small>${escapeHtml(t.detail).replace(/(\d{4})-(\d{2})-(\d{2})/g,'$3/$2/$1')}</small></span><b>Abrir →</b></button>`).join(''):'<div class="empty">Sem reclamações abertas, atividades atrasadas ou mensagens pendentes registradas.</div>'}</section><section class="panel"><div class="panel-head"><h2>Marcos registrados hoje</h2><span class="fine">Atualizações mais recentes · até 12 registros</span></div>${d.milestones.length?d.milestones.map(e=>`<button class="overview-handoff" data-order="${e.order_id}"><span><strong>${escapeHtml(e.title)}${e.type==='payment'?' · '+money(e.value):''}</strong><small>${escapeHtml(e.context)}</small></span><small>${e.at.length===10?'Data informada':new Date(e.at).toLocaleTimeString('pt-BR',{timeZone:'America/Sao_Paulo',hour:'2-digit',minute:'2-digit'})}</small></button>`).join(''):'<p class="muted">Nenhum marco de pagamento, reclamação ou produção registrado hoje.</p>'}</section><div class="banner ${c.pending_events?'':'success'}">${c.pending_events?`${c.pending_events} evento(s) financeiro(s) aguardam conciliação. Confira antes de tomar decisões de cobrança.`:'Nenhum evento financeiro pendente de conciliação registrado.'}</div><p class="fine">Contagens e valores consultam o banco completo do portal. Não representam lucro ou saldo bancário. A leitura não força uma sincronização com o Asaas. ${f.undated_received} recebimento(s) sem data informada ficam fora dos valores diários. Reclamações são registros explícitos; a última mensagem do cliente indica pedido aguardando resposta, sem inferir seu conteúdo.</p>`;
bindOrderButtons();document.querySelector('#overview-refresh').onclick=loadOverview;document.querySelectorAll('[data-overview]').forEach(b=>b.onclick=()=>overviewGo(b.dataset.overview));document.querySelectorAll('[data-overview-task]').forEach(b=>b.onclick=()=>{overviewGo('tasks');workFilters.selected=b.dataset.overviewTask;});loadOverview.timer=setTimeout(()=>{if(state.tab==='overview'&&state.user&&!state.user.staff_profile)loadOverview()},60000);
}catch(e){const box=document.querySelector('#overview-content');if(box)box.innerHTML='<div class="panel empty">Não foi possível atualizar o resumo. Use Atualizar agora para tentar novamente.</div>';document.querySelector('#overview-refresh')?.addEventListener('click',loadOverview,{once:true});notify(e.message,true);}}
function overviewGo(kind){if(['late','today','unassigned','blocked','tasks'].includes(kind)){Object.assign(workFilters,{archive:'active',query:'',status:kind==='blocked'?'blocked':'open',priority:'',deadline:kind==='late'?'late':kind==='today'?'today':'',assignee:kind==='unassigned'?'none':'',kind:'',sort:'recommended',selected:null});state.tab='activity';}else if(['finance','bi'].includes(kind)){state.tab=kind;}else{Object.assign(opsFilters,{query:'',stage:kind==='ready'?'approved':kind==='review'?'review':'',product:'',signal:kind==='messages'?'unanswered':kind==='complaints'?'complaint':kind==='materials'?'materials-review':'',assignee:'',payment:'',from:kind==='new'?new Date().toLocaleDateString('en-CA',{timeZone:'America/Sao_Paulo'}):'',to:'',sort:'attention',page:1});state.tab='orders';}render();}

function workClientContext(t){const c=t.context||{},labels={company_name:'Empresa',company_intro:'Apresentação enviada',services:'Serviços informados',domain:'Domínio',email:'E-mail',phone:'Telefone',whatsapp:'WhatsApp',address:'Endereço',notes:'Orientações do cliente'},format=v=>new Date(v.length===10?v+'T12:00:00Z':v).toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo'});let html='';
if(c.request)html+=`<section class="work-request"><div class="panel-head"><h3>${escapeHtml(c.source)}</h3><span class="badge">Texto original</span></div><blockquote>${escapeHtml(c.request.body)}</blockquote><p class="fine">${escapeHtml(c.request.author)} · ${escapeHtml(format(c.request.at))}</p></section>`;
else if(['message','changes','complaint','publish'].includes(t.kind))html+='<div class="banner">Não foi localizado o relato original vinculado a esta atividade. Confira o histórico do pedido antes de executar.</div>';
if(c.payment)html+=`<section class="work-request"><h3>Cobrança a conferir</h3><p><strong>${money(c.payment.value_cents)}</strong> · Vencimento ${date(c.payment.due_date)} · ${badge(c.payment.status)}</p><p class="fine">Confira a situação atual antes de contatar o cliente.</p></section>`;
if(c.briefing){const fields=Object.entries(c.briefing.fields).filter(([,v])=>v);html+=`<details class="work-client-briefing" ${['produce','review'].includes(t.kind)?'open':''}><summary>Informações enviadas pelo cliente · ${escapeHtml(c.briefing.fields.company_name||'briefing')}</summary><p class="fine">${briefingStates[c.briefing.status]||escapeHtml(c.briefing.status)} · versão ${c.briefing.version} · ${date(c.briefing.at)} · Dados atuais do briefing</p><dl>${fields.map(([k,v])=>`<div><dt>${labels[k]}</dt><dd>${escapeHtml(v)}</dd></div>`).join('')||'<p class="muted">Nenhum campo preenchido.</p>'}</dl></details>`;}
if(c.files?.length)html+=`<section class="work-source-files"><h3>Arquivos enviados pelo cliente</h3><div class="row-buttons">${c.files.map(f=>`<a class="btn secondary" href="/api/orders/${t.order_id}/materials/${f.id}" download>${escapeHtml(f.original_name)} ↓</a>`).join('')}</div></section>`;
else if(['review','produce','changes','publish'].includes(t.kind))html+='<p class="fine">Nenhum arquivo anexado neste pedido.</p>';
return html;}

function newManualTask(d){const manager=!state.user.staff_profile,requestId=crypto.randomUUID();showDialog(`<span class="eyebrow">Nova atividade</span><h2>O que precisa ser feito?</h2><form id="manual-task-create"><label class="field"><span>Título da atividade *</span><input name="title" required minlength="5" maxlength="160" placeholder="Ex.: Preparar proposta de aplicativo para o cliente"></label><label class="field"><span>Descrição e orientações *</span><textarea name="instructions" required minlength="10" maxlength="6000" placeholder="Explique a entrega esperada, o contexto e as informações necessárias para executar."></textarea></label><div class="team-form"><label class="field"><span>Responsável *</span>${manager?`<select name="assignee_id"><option value="${state.user.id}">Eu · ${escapeHtml(state.user.name)}</option>${d.members.filter(m=>m.active&&m.id!==state.user.id).map(m=>`<option value="${m.id}">${escapeHtml(m.name)}</option>`).join('')}</select>`:`<input value="${escapeHtml(state.user.name)} · você" readonly><input name="assignee_id" type="hidden" value="${state.user.id}">`}</label><label class="field"><span>Prazo *</span><input name="due_date" type="date" required value="${d.today}"></label><label class="field"><span>Prioridade *</span><select name="priority">${Object.entries(workPriority).map(([k,v])=>`<option value="${k}" ${k==='normal'?'selected':''}>${v}</option>`).join('')}</select></label><label class="field"><span>Pedido relacionado (opcional)</span><select name="order_id"><option value="">Atividade interna · sem pedido</option>${d.task_orders.map(o=>`<option value="${o.id}">${escapeHtml(o.title)}</option>`).join('')}</select></label></div><label class="field"><span>Resultado esperado (opcional)</span><input name="goal" maxlength="500" placeholder="Ex.: Proposta pronta para conferência"></label><label class="field"><span>Checklist (opcional) · um passo por linha</span><textarea name="steps" placeholder="Levantar informações\nPreparar documento\nConferir entrega"></textarea></label><p class="fine">${manager?'Você acompanha todas as atividades da equipe, incluindo as criadas pelos colaboradores.':'A atividade será atribuída a você. Cada colaborador visualiza somente as próprias atividades; a administração acompanha toda a equipe.'} A atividade pode ser interna ou vinculada a um pedido acessível.</p><button class="btn orange">Cadastrar atividade</button></form>`);document.querySelector('#manual-task-create').onsubmit=e=>{e.preventDefault();task(e.submitter,async()=>{const values=Object.fromEntries(new FormData(e.target)),steps=values.steps.split(/\r?\n/).map(s=>s.trim()).filter(Boolean);await post('/api/team/tasks',{...values,action:'create-task',requestId,steps});dialog.close();Object.assign(workFilters,{query:'',status:'open',priority:'',deadline:'',assignee:'',kind:'manual',sort:'recent',selected:requestId});await loadWork();notify('Atividade cadastrada na fila do responsável.');})};}

function taskManagementButtons(t){return `<div class="task-management-actions">${t.can_edit?'<button class="btn secondary" type="button" data-task-manage="edit-task">Editar atividade</button>':''}${t.can_cancel?'<button class="btn danger" type="button" data-task-manage="cancel-task">Cancelar atividade</button>':''}${t.can_archive?'<button class="btn secondary" type="button" data-task-manage="archive-task">Arquivar</button>':''}${t.can_restore?'<button class="btn secondary" type="button" data-task-manage="restore-task">Restaurar do arquivo</button>':''}${t.status==='canceled'?'<span class="badge bad">Cancelada · histórico preservado</span>':''}${t.archived_at?'<span class="badge">Arquivada</span>':''}</div>`;}
function manageTaskDialog(t,d,action){const edit=action==='edit-task',manager=!state.user.staff_profile,labels={'edit-task':'Editar atividade','cancel-task':'Cancelar atividade','archive-task':'Arquivar atividade','restore-task':'Restaurar atividade do arquivo'};showDialog(`<span class="eyebrow">Gestão de atividades</span><h2>${labels[action]}</h2><p>${escapeHtml(t.title)}</p><form id="task-management-form">${edit?`<label class="field"><span>Título *</span><input name="title" required minlength="5" maxlength="160" value="${escapeHtml(t.title)}"></label><label class="field"><span>Descrição e instruções *</span><textarea name="instructions" required minlength="10" maxlength="6000">${escapeHtml(t.instructions)}</textarea></label><label class="field"><span>Resultado esperado</span><input name="goal" maxlength="500" value="${escapeHtml(t.goal)}"></label><div class="team-form"><label class="field"><span>Prazo *</span><input type="date" name="due_date" required value="${t.due_date}"></label><label class="field"><span>Prioridade *</span><select name="priority">${Object.entries(workPriority).map(([k,v])=>`<option value="${k}" ${t.priority===k?'selected':''}>${v}</option>`).join('')}</select></label>${manager?`<label class="field"><span>Responsável</span><select name="assignee_id">${t.kind!=='manual'?'<option value="">Sem responsável</option>':''}<option value="${state.user.id}" ${t.assignee_id===state.user.id?'selected':''}>Eu · ${escapeHtml(state.user.name)}</option>${d.members.filter(m=>m.id!==state.user.id&&(m.active||m.id===t.assignee_id)).map(m=>`<option value="${m.id}" ${m.id===t.assignee_id?'selected':''}>${escapeHtml(m.name)}${m.active?'':' · Desativado'}</option>`).join('')}</select></label>`:''}</div><label class="field"><span>Checklist · um passo por linha</span><textarea name="steps">${escapeHtml(t.checklist.map(c=>c.label).join('\n'))}</textarea></label><p class="fine">Passos com o mesmo texto mantêm a conferência anterior. Novos passos começam pendentes. O texto original enviado pelo cliente permanece preservado.</p>`:action==='cancel-task'?'<div class="banner">A atividade sairá da fila de execução e o histórico será preservado. Cancelar esta atividade não cancela o pedido nem resolve uma reclamação.</div>':action==='archive-task'?'<div class="banner">A atividade permanecerá acessível pelo filtro Arquivadas. O histórico será preservado.</div>':'<div class="banner">A atividade voltará a aparecer fora do arquivo, mantendo a situação de concluída ou cancelada.</div>'}<label class="field"><span>Motivo *</span><textarea name="reason" required minlength="5" maxlength="4000" placeholder="Explique a alteração para manter o histórico claro."></textarea></label><button class="btn ${action==='cancel-task'?'danger':'orange'}">${labels[action]}</button></form>`);document.querySelector('#task-management-form').onsubmit=e=>{e.preventDefault();task(e.submitter,async()=>{const values=Object.fromEntries(new FormData(e.target));if(edit){values.steps=values.steps.split(/\r?\n/).map(v=>v.trim()).filter(Boolean);values.assignee_id=manager?values.assignee_id:t.assignee_id;}await post('/api/team/tasks',{...values,action,id:t.id,version:t.version});dialog.close();workFilters.selected=t.id;if(action==='cancel-task'){workFilters.status='canceled';workFilters.archive='active';}if(action==='archive-task'){workFilters.archive='archived';workFilters.status='all';}if(action==='restore-task'){workFilters.archive='active';workFilters.status=t.status;}await loadWork();notify('Atividade atualizada com histórico preservado.');})};}

dialog.addEventListener('close',()=>{if(state.user?.role==='client'&&state.tab==='orders')renderView();});
